S="C:/Users/admin/AppData/Local/Temp/claude/0d7dbb6b985a7ec7/a3ee91ab-a830-4247-a1df-9badebb26daf/scratchpad"; mkdir -p "$S/txt"; cat > "$S/conv.py" <<'EOF'
import sys, os, docx, openpyxl
src, out = sys.argv[1], sys.argv[2]
for f in os.listdir(src):
    p = os.path.join(src, f)
    if f.startswith('~$'): continue
    base = os.path.join(out, f + '.txt')
    lines = []
    if f.endswith('.docx'):
        d = docx.Document(p)
        body = d.element.body
        from docx.table import Table
        from docx.text.paragraph import Paragraph
        for el in body.iterchildren():
            tag = el.tag.split('}')[1]
            if tag == 'p':
                para = Paragraph(el, d)
                t = para.text.strip()
                if t:
                    st = para.style.name if para.style is not None else ''
                    pre = '#' * int(st.split()[-1]) + ' ' if st.startswith('Heading') and st.split()[-1].isdigit() else ''
                    lines.append(pre + t)
            elif tag == 'tbl':
                tb = Table(el, d)
                for r in tb.rows:
                    cells = []
                    for c in r.cells:
                        v = c.text.strip().replace('\n', ' / ')
                        if not cells or cells[-1] != v: cells.append(v)
                    lines.append('| ' + ' | '.join(cells) + ' |')
                lines.append('')
    elif f.endswith('.xlsx'):
        wb = openpyxl.load_workbook(p, data_only=True, read_only=True)
        for ws in wb.worksheets:
            lines.append(f'=== SHEET: {ws.title} ===')
            for r in ws.iter_rows(values_only=True):
                if any(v not in (None, '') for v in r):
                    lines.append(' | '.join('' if v is None else str(v).replace('\n',' / ') for v in r).rstrip(' |'))
    open(base, 'w', encoding='utf-8').write('\n'.join(lines))
    print(f, len(lines))
EOF
python -I "$S/conv.py" "D:/[NADAT]/Project/NDOP/Train AI NDOP/Input" "$S/txt" && wc -c "$S/txt"/*

