window.__ex = async (maxIter=15, stopLabels=[]) => {
 const ml=document.querySelector('.MessageList'); const store=new Map();
 const grab=()=>{ document.querySelectorAll('.message-date-group').forEach(g=>{ const d=g.querySelector('.sticky-date')?.innerText||''; let sender='';
   g.querySelectorAll('.Message, .ActionMessage').forEach(m=>{ const id=m.id||m.dataset.messageId; const t=m.querySelector('.message-title')?.innerText; if(t) sender=t.split('\n')[0];
     const tx=m.querySelector('.text-content')?.innerText?.replace(/\n?\d{1,2}:\d{2}( (AM|PM))?$/,'')||''; const time=m.querySelector('.message-time')?.innerText||''; const file=[...m.querySelectorAll('.file-title, .File .title')].map(e=>'[FILE: '+e.innerText+']').join(' '); const rep=m.querySelector('.EmbeddedMessage')?.innerText?.replace(/\n/g,' ').slice(0,80);
     const act=m.classList.contains('ActionMessage')?'[ACT] '+m.innerText:''; 
     if(id && !store.has(id)) store.set(id, {d, time, sender: act?'':sender, tx: act || ((rep?'(re: '+rep+') ':'')+tx+' '+file).trim()}); }); }); };
 for(let i=0;i<maxIter;i++){ grab(); const top=document.querySelector('.sticky-date')?.innerText; if(stopLabels.some(s=>[...document.querySelectorAll('.sticky-date')].some(e=>e.innerText.includes(s)))) break; ml.scrollTop=0; await new Promise(r=>setTimeout(r,1200)); }
 grab();
 const arr=[...store.entries()].sort((a,b)=>{const na=parseInt((a[0]+'').replace(/\D/g,'')), nb=parseInt((b[0]+'').replace(/\D/g,'')); return na-nb;}).map(e=>e[1]);
 let out='', lastD=''; arr.forEach(x=>{ if(x.d!==lastD){out+='\n## '+x.d+'\n'; lastD=x.d;} out+=`[${x.time}] ${x.sender}: ${x.tx.replace(/\n+/g,' / ')}\n`; });
 return out; };
const r = await window.__ex(1); r.length + '\n' + r.slice(0,1500)

