import sys
p = sys.argv[1]
s = open(p, encoding='utf-8').read()

def rep(a, b):
    global s
    assert a in s, a[:70]
    s = s.replace(a, b, 1)

rep('const dvOf=r=>DV[r.ma]||r.donvi||r.ma;', 'const dvOf=r=>r.dv||DV[r.ma]||r.donvi||r.ma;')
rep('nguoi_lam:"Người làm",nhom_chat:"Nhóm chat"};', 'nguoi_lam:"Người làm",nhom_chat:"Nhóm chat",dv:"Đơn vị",luong:"Tên luồng",nhom:"Nhóm đơn vị",nv:"Nghiệp vụ"};')
rep('$("dBody").innerHTML=`<div class="row2">${inp("ba","BA phụ trách")}${inp("dev","Dev NADAT")}</div>',
    '$("dBody").innerHTML=`<div class="row2"><div class="fld"><label for="f_dv">Đơn vị</label><input id="f_dv" value="${esc(dvOf(r))}"></div>${inp("luong","Tên luồng")}</div><div class="row2"><div class="fld"><label for="f_nhom">Nhóm đơn vị</label><select id="f_nhom">${CATORDER.map(c=>`<option value="${c}" ${c===r.nhom?"selected":""}>${CAT[c]}</option>`).join("")}</select></div>${inp("nv","Nghiệp vụ (TH / CS / ĐP)")}</div><div class="row2">${inp("ba","BA phụ trách")}${inp("dev","Dev NADAT")}</div>')
rep('<div class="sec"><h4>Lịch sử thay đổi</h4><div class="hist" id="dHist"></div></div>`;',
    '<div class="sec"><h4>Lịch sử thay đổi</h4><div class="hist" id="dHist"></div></div><div><button class="btn sm" type="button" id="lDel">Xoá luồng này</button></div>`;\n  {let armed=false;$("lDel").onclick=async()=>{if(!armed){armed=true;$("lDel").textContent="Bấm lần nữa để xoá";return}try{await S.db.collection("luong").doc(r._id).delete();toast("Đã xoá luồng.");closeD()}catch(e){toast("Chưa xoá được. Bạn cần quyền sửa.")}}}')
rep('const v=el.value.trim(),old=k.endsWith("_tt")?stOf(r[k]):(r[k]||"");', 'const v=el.value.trim(),old=k.endsWith("_tt")?stOf(r[k]):k==="dv"?dvOf(r):(r[k]||"");')

BLOCK = r'''
/* ---------- Sửa trực tiếp các danh sách ---------- */
const BENS=["Nội bộ NADAT","Chủ đầu tư – C12","Nhà thầu, hệ thống trong NDC","Bộ, ngành","Địa phương","Doanh nghiệp","Chưa rõ đơn vị"];
const TLTT=["Có sẵn","Đã tải","Chưa tải","Đang làm","Không tải"];
function showForm(title,sub,fields,onSave,onDel){
  S.unit=null;S.edit=null;S.form={fields,onSave};
  $("dTitle").textContent=title;$("dSub").textContent=sub||"";$("dFoot").hidden=false;$("dBack").hidden=true;
  $("dBody").innerHTML=fields.map(f=>`<div class="fld"><label for="g_${f.k}">${esc(f.l)}</label>${f.o?`<select id="g_${f.k}">${f.o.map(o=>`<option ${o===f.v?"selected":""}>${esc(o)}</option>`).join("")}</select>`:f.t==="area"?`<textarea id="g_${f.k}">${esc(f.v||"")}</textarea>`:`<input id="g_${f.k}" value="${esc(f.v||"")}" ${f.list?`list="${f.list}"`:""}>`}</div>`).join("")+(onDel?`<div><button class="btn sm" type="button" id="gDel">Xoá mục này</button></div>`:"");
  if(onDel){let armed=false;$("gDel").onclick=()=>{if(!armed){armed=true;$("gDel").textContent="Bấm lần nữa để xoá";return}run(onDel,"Đã xoá.")}}
  const ro=S.canWrite===false;$("dSave").disabled=ro||!S.db;$("dPerm").textContent=ro?"Bạn chỉ có quyền xem.":"";openD();
}
async function run(fn,msg){if(!S.db)return;try{const r=await fn();if(r===false)return;toast(msg);closeD()}catch(e){toast(/permission|not_granted/.test(e&&e.code||"")?"Bạn chưa có quyền sửa. Nhờ chủ trang cấp quyền Contributor.":"Chưa lưu được. Kiểm tra kết nối rồi thử lại.")}}
const vals=()=>{const o={};S.form.fields.forEach(f=>o[f.k]=$("g_"+f.k).value.trim());return o};
{const c0=closeD,e0=showEdit,u0=showUnit;closeD=function(){S.form=null;c0()};showEdit=function(i){S.form=null;e0(i)};showUnit=function(n){S.form=null;u0(n)};
 $("dClose").onclick=()=>closeD();$("scrim").onclick=()=>closeD();$("dSave").onclick=()=>S.form?run(()=>S.form.onSave(vals()),"Đã lưu."):save();}

function rPeople(){
  const cnt=b=>S.nguoi.filter(g=>g.ben===b).reduce((a,g)=>a+g.nguoi.length,0);
  seg("segBen",[["","Tất cả"],...BENS.map(b=>[b,`${b} (${cnt(b)})`])],S.ben,v=>{S.ben=v;rPeople()});
  let dl=$("dlDv");if(!dl){dl=document.createElement("datalist");dl.id="dlDv";document.body.appendChild(dl)}dl.innerHTML=S.nguoi.map(g=>`<option>${esc(g.dv)}</option>`).join("");
  const q=norm($("qNg").value);
  const gs=S.nguoi.filter(g=>!S.ben||g.ben===S.ben).sort((a,b)=>BENS.indexOf(a.ben)-BENS.indexOf(b.ben)).map(g=>({g,ps:g.nguoi.map((p,i)=>({p,i})).filter(x=>!q||norm(g.dv+" "+Object.values(x.p).join(" ")).includes(q))})).filter(x=>x.ps.length);
  $("ngGroups").innerHTML=gs.map(({g,ps})=>`<div class="card"><div class="grp"><h3>${esc(g.dv)}</h3><span>${ownTagBen(g.ben)} · ${ps.length} người</span></div><div class="tbl"><table><thead><tr><th style="width:24%">Họ tên</th><th style="width:18%">Tài khoản chat</th><th style="width:18%">Phòng ban</th><th>Vai trò, phụ trách</th><th style="width:20%">Nhóm chat</th></tr></thead><tbody>${ps.map(({p,i})=>`<tr class="go" data-ng="${esc(g._id)}|${i}"><td><div class="t">${esc(p.ho_ten)}</div>${p.can_cu?`<div class="d">Căn cứ: ${esc(p.can_cu)}</div>`:""}</td><td class="d">${esc(p.tai_khoan)||"—"}</td><td>${esc(p.phong_ban)||`<span class="d">chưa rõ</span>`}</td><td class="d">${esc(p.vai_tro)}</td><td class="d">${esc(p.nhom_chat)}</td></tr>`).join("")}</tbody></table></div></div>`).join("")||`<div class="card empty">${S.loaded?"Không có người khớp.":"Đang tải…"}</div>`;
}
function editPerson(gid,idx){
  const g=S.nguoi.find(x=>x._id===gid),p=g&&idx>=0?g.nguoi[idx]:{};
  showForm(p.ho_ten||"Thêm stakeholder",g?g.dv:"",[{k:"ho_ten",l:"Họ tên",v:p.ho_ten},{k:"tai_khoan",l:"Tài khoản trên nhóm chat",v:p.tai_khoan},{k:"dv",l:"Đơn vị",v:g?g.dv:"",list:"dlDv"},{k:"ben",l:"Thuộc bên",o:BENS,v:g?g.ben:"Chưa rõ đơn vị"},{k:"phong_ban",l:"Phòng ban",v:p.phong_ban},{k:"vai_tro",l:"Vai trò, phụ trách việc gì",v:p.vai_tro,t:"area"},{k:"nhom_chat",l:"Tham gia nhóm chat",v:p.nhom_chat,t:"area"},{k:"can_cu",l:"Căn cứ (vì sao biết)",v:p.can_cu}],
  async v=>{if(!v.ho_ten||!v.dv){toast("Cần nhập họ tên và đơn vị.");return false}
    const person=Object.assign({},p,{ho_ten:v.ho_ten,tai_khoan:v.tai_khoan,phong_ban:v.phong_ban,vai_tro:v.vai_tro,nhom_chat:v.nhom_chat,can_cu:v.can_cu,nguon:p.nguon||"Nhập tay"});
    const col=S.db.collection("nguoi"),t=S.nguoi.find(x=>x.dv===v.dv);
    if(g&&t&&t._id===g._id){const a=[...g.nguoi];idx>=0?a[idx]=person:a.push(person);await col.doc(g._id).set({dv:g.dv,ben:v.ben,nguoi:a})}
    else{if(t)await col.doc(t._id).set({dv:t.dv,ben:t.ben,nguoi:[...t.nguoi,person]});else await col.doc("dv"+Date.now()).set({dv:v.dv,ben:v.ben,nguoi:[person]});
      if(g&&idx>=0)await col.doc(g._id).set({dv:g.dv,ben:g.ben,nguoi:g.nguoi.filter((_,i)=>i!==idx)})}},
  g&&idx>=0?()=>S.db.collection("nguoi").doc(g._id).set({dv:g.dv,ben:g.ben,nguoi:g.nguoi.filter((_,i)=>i!==idx)}):null);
}
function rChat(){
  const q=norm($("qChat").value),p=$("fPlat").value;
  const rows=S.nhomchat.filter(r=>(!p||r.nen_tang===p)&&(!q||norm(Object.values(r).join(" ")).includes(q)));
  $("tbChat").innerHTML=rows.map(r=>`<tr class="go" data-nc="${esc(r._id)}"><td><span class="tag">${esc(r.nen_tang)}</span></td><td class="t">${esc(r.ten)}</td><td class="d">${esc(r.ma_luong)}</td><td>${esc(r.ba)}</td><td>${/KHÔNG|CHƯA/.test(r.doc_cuoi)?`<span class="pill p-block">${esc(r.doc_cuoi)}</span>`:esc(r.doc_cuoi)}<div class="d">tin mới nhất ${esc(r.tin_moi)}</div></td><td class="d">${esc(r.ghi_chu)}</td></tr>`).join("")||`<tr><td colspan="6" class="empty">${S.loaded?"Không có nhóm khớp.":"Đang tải…"}</td></tr>`;
}
function editChat(id){
  const r=S.nhomchat.find(x=>x._id===id)||{};
  showForm(r.ten||"Thêm nhóm chat","",[{k:"nen_tang",l:"Nền tảng",o:["Telegram","WhatsApp","Zalo","Viber"],v:r.nen_tang||"Telegram"},{k:"ten",l:"Tên nhóm",v:r.ten},{k:"ma_luong",l:"Luồng, đơn vị liên quan",v:r.ma_luong},{k:"ba",l:"BA phụ trách",v:r.ba},{k:"doc_cuoi",l:"Đọc lần cuối",v:r.doc_cuoi},{k:"tin_moi",l:"Tin mới nhất",v:r.tin_moi},{k:"ghi_chu",l:"Ghi chú",v:r.ghi_chu,t:"area"}],
  async v=>{if(!v.ten){toast("Cần nhập tên nhóm.");return false}const c=S.db.collection("nhomchat");if(r._id)await c.doc(r._id).set(v);else await c.add(v)},
  r._id?()=>S.db.collection("nhomchat").doc(r._id).delete():null);
}
function rDocs(){
  const q=norm($("qTl").value);
  $("tlGroups").innerHTML=[...S.tailieu].sort((a,b)=>(a.thu_tu||9)-(b.thu_tu||9)).map(g=>{const ms=(g.muc||[]).map((m,i)=>({m,i})).filter(x=>!q||norm(Object.values(x.m).join(" ")).includes(q));return ms.length?`<div class="card"><div class="grp"><h3>${esc(g.ten)}</h3><span>${ms.length} mục</span></div><div class="tbl"><table><thead><tr><th style="width:46%">Tài liệu</th><th>Loại</th><th>Nguồn</th><th>Trạng thái</th><th></th></tr></thead><tbody>${ms.map(({m,i})=>docRow(m).replace("<tr>",`<tr class="go" data-tl="${esc(g._id)}|${i}">`)).join("")}</tbody></table></div></div>`:""}).join("")||`<div class="card empty">${S.loaded?"Chưa có tài liệu khớp.":"Đang tải…"}</div>`;
}
