  const upd=S.luong.filter(r=>inR(pDate(r.cap_nhat))).sort((a,b)=>String(dvOf(a)).localeCompare(String(dvOf(b)),"vi"));
  const nk=S.nhatky.filter(x=>inR(new Date(x.at)));
  const moved=[],cleared=[];nk.forEach(x=>(x.thay_doi||[]).forEach(c=>{const r=S.luong.find(y=>y._id===x.luong);const n=r?`${dvOf(r)} (${r.ma})`:x.luong;if(/_tt$/.test(c.truong))moved.push(`${n}: ${c.truong==="ndc_tt"?"NDC":"DevTest/103NT"} ${c.cu||"—"} → ${c.moi}`);if(c.truong==="blocker"&&(!c.moi||c.moi==="—")&&c.cu&&c.cu!=="—")cleared.push(`${n}: ${c.cu}`)}));
  const newB=o.filter(r=>inR(bDate(r))),late=S.luong.filter(r=>lateDays(r)>0),mmOpen=S.momang.filter(m=>mmWait(m)!=="Xong");
  const own=k=>o.filter(r=>owners(r).includes(k)).length;
  const L=[];
  L.push(`BÁO CÁO TIẾN ĐỘ ĐẤU NỐI NDOP`,`Kỳ báo cáo: ${vn(f)} – ${vn(t)}`,"");
  L.push("1. Tổng quan",`- ${U.length} đơn vị, hệ thống; ${S.luong.length} luồng đấu nối.`,`- Xong DevTest/103NT: ${U.filter(u=>u.dt==="Hoàn thành").length} đơn vị. Xong NDC: ${U.filter(u=>u.ndc==="Hoàn thành").length} đơn vị.`,`- Đang bị chặn: ${U.filter(u=>u.dt==="Bị block"||u.ndc==="Bị block").length} đơn vị. Vướng mắc đang mở: ${o.length} (nội bộ NADAT ${own("Nội bộ NADAT")}, C12/hạ tầng ${own("C12 / hạ tầng")}, đối tác ${own("Đối tác")}).`,"");
  L.push(`2. Chuyển trạng thái trong kỳ (${moved.length})`,...(moved.length?moved.map(x=>"- "+x):["- Không có thay đổi trạng thái được ghi trên trang."]),"");
  L.push(`3. Luồng có cập nhật trong kỳ (${upd.length})`,...(upd.length?upd.map(r=>`- ${dvOf(r)} (${r.ma}) – DevTest/103NT: ${stOf(r.dt_tt)}; NDC: ${stOf(r.ndc_tt)}. Tiếp theo: ${r.viec_tiep||"—"}`):["- Không có."]),"");
  L.push(`4. Vướng mắc mới phát sinh (${newB.length})`,...(newB.length?newB.map(r=>`- ${dvOf(r)} (${r.ma}): ${r.blocker} – đang chặn: ${r.ai_chan||"—"}`):["- Không có."]),"");
  L.push(`5. Vướng mắc đã gỡ (${cleared.length})`,...(cleared.length?cleared.map(x=>"- "+x):["- Chưa ghi nhận trên trang."]),"");
  L.push(`6. Việc quá hạn (${late.length})`,...(late.length?late.map(r=>`- ${dvOf(r)} (${r.ma}): ${r.viec_tiep||"—"} – ${r.nguoi_lam||r.ba||"chưa giao"}, hạn ${r.han_xu_ly}`):["- Không có (hoặc chưa đặt hạn)."]),"");
  L.push(`7. Mở mạng NDC chưa xong (${mmOpen.length})`,...(mmOpen.length?mmOpen.map(m=>`- ${m.don_vi}: ${m.chieu||""} – ${mmWait(m)}`):["- Không có."]),"");
  const top=o.map(r=>({r,d:days(bDate(r))})).sort((a,b)=>(b.d??-1)-(a.d??-1)).slice(0,5);
  L.push("8. Đề nghị hỗ trợ (vướng lâu nhất)",...top.map(({r,d})=>`- ${dvOf(r)} (${r.ma}, ${d??"?"} ngày): ${r.blocker} – đề nghị ${r.ai_chan||"các bên"} xử lý.`));
  $("bcText").textContent=L.join("\n");
}
