1	<title>Đấu nối NDOP</title>
2	<meta name="claude:viewport-fit-sides" content="cover">
3	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Noto+Sans:wght@400;600;700&display=swap">
4	<style>
5	/* Bố cục: cột điều hướng trái + nội dung một cột rộng tối đa 1180px; một kiểu thẻ, một cặp nút, một bán kính 8px. Chỉ giao diện sáng (theo yêu cầu). */
6	:root{color-scheme:light;
7	  --canvas:#f5f6f8;--surface:#ffffff;--hover:#f7f7f8;--line:#e4e6ea;--line-2:#d0d4da;
8	  --ink:#161a22;--ink-2:#3b4250;--ink-3:#5c6472;
9	  --brand:#a16207;--brand-dark:#854a0e;--brand-soft:#fdf6e3;
10	  --ok:#067647;--ok-bg:#e9f9ef;--run:#1d4ed8;--run-bg:#eaf1ff;--wait:#b54708;--wait-bg:#fff4e0;--block:#b42318;--block-bg:#fdecea;--mute:#475467;--mute-bg:#eef0f3;
11	  --font:"Inter","Noto Sans",-apple-system,"Segoe UI",Roboto,Arial,sans-serif;--r:8px;--shadow:0 1px 2px rgba(16,24,40,.06)}
12	*{box-sizing:border-box}
13	html,body{height:100%}
14	body{background:var(--canvas);color:var(--ink);font:400 15px/22px var(--font)}
15	.app{display:grid;grid-template-columns:232px minmax(0,1fr);min-height:100%}
16	.side{background:var(--surface);border-right:1px solid var(--line);padding:20px 12px;position:sticky;top:0;align-self:start;height:100vh;overflow:auto;display:flex;flex-direction:column;gap:4px}
17	.side h1{font-size:17px;line-height:24px;font-weight:700;margin:0 8px 2px}
18	.side .sub{font-size:12px;line-height:16px;color:var(--ink-3);margin:0 8px 14px}
19	.side a{display:flex;justify-content:space-between;align-items:center;gap:8px;min-height:44px;padding:0 12px;border-radius:var(--r);color:var(--ink-2);text-decoration:none;font-weight:500;transition:background .12s}
20	.side a:hover{background:var(--hover)}
21	.side a[aria-current="page"]{background:var(--brand-soft);color:var(--brand-dark);font-weight:600}
22	.side a b{font-weight:600;font-size:12px;color:var(--ink-3);font-variant-numeric:tabular-nums}
23	.side .sync{margin-top:auto;padding:10px 12px;font-size:12px;line-height:16px;color:var(--ink-3);display:flex;gap:8px;align-items:center}
24	.dot{width:8px;height:8px;border-radius:50%;background:#98a2b3;flex:none}.dot.live{background:#12b76a}
25	main{padding-block:24px 64px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));min-width:0}
26	.col{max-width:1180px;margin:0 auto;display:grid;gap:20px}
27	.head{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end;justify-content:space-between}
28	.head h2{font-size:24px;line-height:32px;font-weight:700;margin:0;text-wrap:balance}
29	.head p{margin:2px 0 0;color:var(--ink-3);font-size:14px;max-width:65ch}
30	.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow)}
31	.pad{padding:16px 20px}
32	.card h3{font-size:16px;line-height:24px;font-weight:600;margin:0}
33	.card .hint{font-size:13px;color:var(--ink-3);margin:2px 0 0}
