36	.kpi.warn .v{color:var(--block)}
37	.pill{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:2px 10px;font-size:12px;line-height:18px;font-weight:600;white-space:nowrap}
38	.pill::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
39	.p-ok{background:var(--ok-bg);color:var(--ok)}.p-run{background:var(--run-bg);color:var(--run)}.p-wait{background:var(--wait-bg);color:var(--wait)}.p-block{background:var(--block-bg);color:var(--block)}.p-pend,.p-none{background:var(--mute-bg);color:var(--mute)}
