42	.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 16px;border-radius:var(--r);border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);font:600 14px/20px var(--font);cursor:pointer;transition:background .12s,transform .08s}
43	.btn:hover{background:var(--hover)}.btn:active{transform:translateY(1px)}
44	.btn.primary{background:var(--brand);border-color:var(--brand);color:#fff}.btn.primary:hover{background:var(--brand-dark)}
