<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Be+Vietnam+Pro:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500&display=swap">
<style>
/* Bố cục: thanh mục trái hẹp + nội dung rộng; hàng bảng dày đặc, nhóm dài thu gọn được. Tương phản cao: chữ gần đen trên nền trắng, viền đậm, trạng thái có viền + chữ đậm để đọc được trên màn hình nhạt. */
:root{color-scheme:light;
  --canvas:#e9edf2;--surface:#ffffff;--hover:#e3ecfb;--line:#aab3c0;--line-2:#6b7686;
  --ink:#05080d;--ink-2:#1b2230;--ink-3:#353e4d;
  --brand:#0a45c2;--brand-dark:#06307f;--brand-soft:#d7e4fc;
  --ok:#04542f;--ok-bg:#c9efd9;--run:#0a3a9e;--run-bg:#d3e1fb;--wait:#7a3500;--wait-bg:#ffe1b8;--block:#8f1209;--block-bg:#ffd3cd;--mute:#2b3442;--mute-bg:#dde2e9;
  --font:"Be Vietnam Pro","Segoe UI",Roboto,Arial,sans-serif;--mono:"IBM Plex Mono",Consolas,monospace;--r:6px}
*{box-sizing:border-box}
html,body{height:100%}
body{background:var(--canvas);color:var(--ink);font:400 14px/20px var(--font)}
.app{display:grid;grid-template-columns:200px minmax(0,1fr);min-height:100%}
.side{background:var(--ink);padding:14px 8px;position:sticky;top:0;align-self:start;height:100vh;overflow:auto;display:flex;flex-direction:column;gap:2px}
.side h1{font-size:16px;line-height:22px;font-weight:700;margin:0 8px 10px;color:#fff}
.side .sub{display:none}
.side a{display:flex;justify-content:space-between;align-items:center;gap:8px;min-height:36px;padding:0 10px;border-radius:var(--r);color:#e6ebf2;text-decoration:none;font-weight:500}
.side a:hover{background:#1f2937}
.side a[aria-current="page"]{background:#fff;color:var(--ink);font-weight:700}
.side a b{font-weight:600;font-size:12px;font-variant-numeric:tabular-nums;opacity:.85}
.side .sync{margin-top:auto;padding:8px 10px;font-size:12px;line-height:16px;color:#cfd6e0;display:flex;gap:8px;align-items:center}
.dot{width:9px;height:9px;border-radius:50%;background:#8a94a3;flex:none}.dot.live{background:#22c55e}
main{padding-block:14px 40px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));min-width:0}
.col{max-width:1400px;margin:0 auto;display:grid;gap:12px}
.head{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center;justify-content:space-between}
.head h2{font-size:20px;line-height:28px;font-weight:700;margin:0;text-wrap:balance}
.head p{display:none}
.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r)}
.pad{padding:10px 14px}
.card h3{font-size:15px;line-height:22px;font-weight:700;margin:0}
.card .hint{font-size:13px;color:var(--ink-3);margin:2px 0 0}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}
.kpi{padding:8px 12px;display:grid;grid-template-columns:auto 1fr;grid-template-areas:"v l" "v s";column-gap:10px;align-items:center}
.kpi .l{grid-area:l;font-size:13px;font-weight:600;color:var(--ink-2)}.kpi .v{grid-area:v;font-size:26px;line-height:32px;font-weight:700;font-variant-numeric:tabular-nums}.kpi .s{grid-area:s;font-size:12px;line-height:16px;color:var(--ink-3)}
.kpi.warn{border-color:var(--block);border-width:2px}.kpi.warn .v{color:var(--block)}
.pill{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:1px 8px;font-size:12px;line-height:18px;font-weight:700;white-space:nowrap;border:1px solid currentColor}
.pill::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.p-ok{background:var(--ok-bg);color:var(--ok)}.p-run{background:var(--run-bg);color:var(--run)}.p-wait{background:var(--wait-bg);color:var(--wait)}.p-block{background:var(--block-bg);color:var(--block)}.p-pend,.p-none{background:var(--mute-bg);color:var(--mute)}
.p-none::before{background:transparent;border:1.5px solid currentColor}
.tag{display:inline-block;border-radius:4px;padding:0 6px;font-size:12px;line-height:18px;font-weight:600;background:var(--mute-bg);color:var(--mute);white-space:nowrap;border:1px solid var(--line)}
.tag.in{background:var(--brand-soft);color:var(--brand-dark);border-color:var(--brand)}.tag.c12{background:var(--wait-bg);color:var(--wait);border-color:var(--wait)}.tag.ext{background:var(--run-bg);color:var(--run);border-color:var(--run)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-height:36px;padding:0 14px;border-radius:var(--r);border:1.5px solid var(--line-2);background:var(--surface);color:var(--ink);font:600 14px/20px var(--font);cursor:pointer}
.btn:hover{background:var(--hover)}.btn:active{transform:translateY(1px)}
.btn.primary{background:var(--brand);border-color:var(--brand);color:#fff}.btn.primary:hover{background:var(--brand-dark)}
.btn:disabled{opacity:.55;cursor:not-allowed}
.btn.sm{min-height:28px;padding:0 8px;font-size:13px}
:focus-visible{outline:3px solid var(--brand);outline-offset:2px}
.scan{display:flex;flex-wrap:wrap;gap:8px 16px;align-items:center;justify-content:space-between}
.scan .txt{min-width:0;flex:1 1 320px;display:flex;flex-wrap:wrap;gap:4px 12px;align-items:baseline}.scan .txt p{margin:0;font-size:13px;color:var(--ink-3)}
.seg{display:flex;flex-wrap:wrap;gap:4px}
.seg button{min-height:30px;padding:0 10px;border-radius:999px;border:1.5px solid var(--line-2);background:var(--surface);color:var(--ink);font:600 13px/18px var(--font);cursor:pointer}
.seg button[aria-pressed="true"]{background:var(--ink);border-color:var(--ink);color:#fff}
.tools{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.tools input,.tools select{min-height:34px;border:1.5px solid var(--line-2);border-radius:var(--r);background:var(--surface);color:var(--ink);padding:0 10px;font:inherit;font-size:14px;min-width:0}
.tools input::placeholder{color:#4a5464}
.tools input[type=search]{flex:1 1 240px}
.tbl{overflow-x:auto}
table{border-collapse:collapse;width:100%}
th{text-align:left;font-size:12px;line-height:16px;font-weight:700;color:var(--ink);padding:6px 10px;border-bottom:2px solid var(--ink);white-space:nowrap;background:var(--mute-bg)}
td{padding:6px 10px;border-bottom:1px solid var(--line);vertical-align:top;font-size:13.5px;line-height:19px}
