rep('<td class="d">${esc(p.vai_tro)}</td><td class="d">${esc(p.nhom_chat)}</td></tr>`).join("")}</tbody></table></div></div>`).join("")',
    '<td class="d"><div class="clamp" title="${esc(p.vai_tro)}">${esc(p.vai_tro)}</div></td><td class="d"><div class="c1" title="${esc(p.nhom_chat)}">${esc(p.nhom_chat)}</div></td></tr>`).join("")}</tbody></table></div></details>`).join("")')
