rep('return ms.length?`<div class="card"><div class="grp"><h3>${esc(g.ten)}</h3><span>${ms.length} mục</span></div><div class="tbl"><table><thead><tr><th style="width:46%">Tài liệu</th><th>Loại</th><th>Nguồn</th><th>Trạng thái</th><th></th></tr></thead><tbody>${ms.map(({m,i})=>docRow(m).replace("<tr>",`<tr class="go" data-tl="${esc(g._id)}|${i}">`)).join("")}</tbody></table></div></div>`:""',
