rep('<td class="d">${esc(r.ghi_chu)}</td></tr>`).join("")||`<tr><td colspan="6"','<td class="d"><div class="clamp" title="${esc(r.ghi_chu)}">${esc(r.ghi_chu)}</div></td></tr>`).join("")||`<tr><td colspan="6"')
