241	</div>
242	
243	<div class="scrim" id="scrim" hidden></div>
244	<aside class="drawer" id="drawer" hidden role="dialog" aria-labelledby="dTitle">
245	  <div class="dh"><div style="flex:1;min-width:0"><h3 id="dTitle"></h3><p id="dSub"></p></div><button class="btn sm" id="dBack" type="button" hidden>Quay lại</button><button class="btn sm" id="dClose" type="button">Đóng</button></div>
246	  <div class="db" id="dBody"></div>
247	  <div class="df" id="dFoot" hidden><span class="d" id="dPerm" style="margin-right:auto"></span><button class="btn" type="button" id="dCancel">Huỷ</button><button class="btn primary" type="button" id="dSave">Lưu thay đổi</button></div>
248	</aside>
249	<div class="toast" id="toast" hidden role="status"></div>
250	
251	<script>
252	const ST=["Chưa bắt đầu","Đang thực hiện","Chờ phản hồi","Bị block","Pending","Hoàn thành"];
253	const CL={"Hoàn thành":"ok","Đang thực hiện":"run","Chờ phản hồi":"wait","Bị block":"block","Pending":"pend","Chưa bắt đầu":"none"};
254	const CAT={"BBN":"Bộ, ban, ngành","ĐP":"Địa phương","HTPM":"Hệ thống trong NDC","DN":"Doanh nghiệp","Nội bộ NDC":"Việc nội bộ tại NDC"};
255	const CATORDER=["BBN","ĐP","HTPM","DN","Nội bộ NDC"];
256	const DV={"CS-01":"PAKN","CS-13":"PAKN","CS-02":"CSDL TTHC","CS-03":"TTTT","CS-04":"Hà Nội","CS-05":"Bộ Tư pháp","TH-BBN-02":"Bộ Tư pháp","CS-06":"Sàn dữ liệu","TH-PM-02":"Sàn dữ liệu","CS-07":"VNPAY","CS-08":"MoMo","CS-09":"VPBank","CS-10":"TPBank","CS-11":"SHB","CS-12":"BIDV","CS-14":"Bộ KHCN","TH-BBN-01":"Bộ KHCN","CS-15":"HT liên lạc","CS-16/17":"Bộ Công an – C06","TH-PM-03":"DMDC","TH-PM-06":"VNPT","TH-BBN-03":"Bộ Xây dựng","TH-BBN-04":"Bộ Nội vụ","TH-BBN-05":"Bộ NN&MT","TH-BBN-06":"NHNN","TH-BBN-07":"Rà soát API Bộ ngành","ĐP-TH":"Thanh Hoá","ĐP-khác":"32 tỉnh còn lại","ĐP-DLSK":"Dữ liệu sai khác","KHO-5.1":"Kho dùng chung","KYSO":"Ký số NDC"};
257	const PEOPLE_OF={"CSDL TTHC":["Cổng DVC"],"HT liên lạc":["HT liên lạc","Gtel"],"Rà soát API Bộ ngành":["Gtel","VNPT"],"Thanh Hoá":["Cổng DVC"]};
258	const F={ba:"BA",dev:"Dev",dt_tt:"Trạng thái DevTest/103NT",dt_buoc:"Bước DevTest/103NT",ndc_tt:"Trạng thái NDC",ndc_buoc:"Bước NDC",blocker:"Vướng mắc",blocker_thuoc:"Thuộc",loai:"Loại",ai_chan:"Ai chặn",viec_tiep:"Việc tiếp theo",nguoi_lam:"Người làm",nhom_chat:"Nhóm chat",han_xu_ly:"Hạn xử lý",dv:"Đơn vị",luong:"Tên luồng",nhom:"Nhóm đơn vị",nv:"Nghiệp vụ"};
259	const S={luong:[],nhomchat:[],nguoi:[],tailieu:[],nhatky:[],quet:null,loaded:false,db:null,user:null,canWrite:null,own:"",ben:"",unit:null,edit:null};
260	const $=i=>document.getElementById(i);
261	const OPEN=new Set();document.addEventListener("toggle",e=>{const k=e.target.dataset&&e.target.dataset.k;if(k)e.target.open?OPEN.add(k):OPEN.delete(k)},true);
262	const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
263	const norm=s=>String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/đ/gi,"d").toLowerCase();
264	const stOf=v=>{v=String(v||"").trim();if(!v||v==="—"||v==="-")return "Chưa bắt đầu";return ST.find(s=>v.startsWith(s))||v};
265	const pill=v=>{const s=stOf(v);return `<span class="pill p-${CL[s]||"none"}">${esc(s)}</span>`};
266	const pDate=s=>{const m=String(s||"").match(/(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?/);return m?new Date(+(m[3]||new Date().getFullYear()),+m[2]-1,+m[1]):null};
267	const days=d=>{if(!d)return null;const t=new Date();t.setHours(0,0,0,0);return Math.max(0,Math.round((t-d)/864e5))};
268	const bDate=r=>{const m=String(r.blocker||"").match(/từ (\d{1,2}\/\d{1,2})/);return pDate(m?m[1]:r.cap_nhat)};
269	const open=r=>{const b=String(r.blocker||"").trim();return b&&b!=="—"&&!(stOf(r.dt_tt)==="Hoàn thành"&&stOf(r.ndc_tt)==="Hoàn thành")};
270	const owners=r=>{const t=norm(r.blocker_thuoc),o=[];if(t.includes("noi bo"))o.push("Nội bộ NADAT");if(/c12|ha tang/.test(t))o.push("C12 / hạ tầng");if(/khach|d01|tttt|gtel|vnpay/.test(t))o.push("Đối tác");return o};
271	const ownTag=o=>`<span class="tag ${o.startsWith("Nội")?"in":o.startsWith("C12")?"c12":"ext"}">${esc(o)}</span>`;
272	const dvOf=r=>r.dv||DV[r.ma]||r.donvi||r.ma;
273	function toast(m){const t=$("toast");t.textContent=m;t.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>t.hidden=true,3500)}
274	function agg(rs,k){const s=rs.map(r=>stOf(r[k]));if(s.includes("Bị block"))return "Bị block";if(s.every(x=>x==="Hoàn thành"))return "Hoàn thành";for(const x of ["Chờ phản hồi","Đang thực hiện","Pending","Hoàn thành"])if(s.includes(x))return x==="Hoàn thành"?"Đang thực hiện":x;return "Chưa bắt đầu"}
275	function units(){const m=new Map();S.luong.forEach(r=>{const k=dvOf(r);if(!m.has(k))m.set(k,{ten:k,cat:r.nhom,rs:[]});m.get(k).rs.push(r)});return [...m.values()].map(u=>Object.assign(u,{dt:agg(u.rs,"dt_tt"),ndc:agg(u.rs,"ndc_tt"),ba:[...new Set(u.rs.map(r=>String(r.ba||"").split(/[(,]/)[0].trim()).filter(Boolean))].join(", "),bl:u.rs.filter(open)}))}
276	function peopleOf(u){const keys=PEOPLE_OF[u]||[u];return S.nguoi.filter(g=>keys.includes(g.dv)).flatMap(g=>g.nguoi.map(p=>Object.assign({dv:g.dv},p)))}
277	
278	/* ---------- Trang ---------- */
279	function rOverview(){
280	  const L=S.luong,U=units(),o=L.filter(open);
281	  if(!S.loaded){$("kpis").innerHTML=`<div class="card kpi"><div class="l">Đang tải dữ liệu…</div></div>`;return}
282	  const inner=o.filter(r=>owners(r).includes("Nội bộ NADAT")).length;
283	  $("kpis").innerHTML=[["Đơn vị, hệ thống",U.length,`${L.length} luồng đấu nối`,""],["Xong DevTest/103NT",U.filter(u=>u.dt==="Hoàn thành").length,"đơn vị đã ký BBNT",""],["Xong NDC",U.filter(u=>u.ndc==="Hoàn thành").length,"đơn vị đã ký BBNT trên NDC",""],["Đang bị chặn",U.filter(u=>u.dt==="Bị block"||u.ndc==="Bị block").length,"đơn vị có luồng Bị block","warn"],["Vướng mắc nội bộ",inner,`trên ${o.length} vướng mắc đang mở`,inner?"warn":""]].map(([l,v,s,c])=>`<div class="card kpi ${c}"><div class="l">${l}</div><div class="v">${v}</div><div class="s">${s}</div></div>`).join("");
284	  const top=o.map(r=>({r,d:days(bDate(r))})).sort((a,b)=>(b.d??-1)-(a.d??-1)).slice(0,7);
285	  $("tbTop").innerHTML=top.map(({r,d})=>`<tr class="go" data-luong="${esc(r._id)}"><td class="num ${d>=14?"hot":""}">${d??"?"} ngày</td><td><div class="t">${esc(dvOf(r))}</div><div class="d">${esc(r.ma)}</div></td><td><div class="clamp">${esc(r.blocker)}</div></td><td>${owners(r).map(ownTag).join(" ")}</td></tr>`).join("")||`<tr><td class="empty">Không có vướng mắc đang mở.</td></tr>`;
286	  const last=L.map(r=>pDate(r.cap_nhat)).filter(Boolean).sort((a,b)=>b-a)[0];
287	  $("asof").textContent=`Tiến độ trên hai môi trường: DevTest/103NT và NDC (Hòa Lạc). Cập nhật gần nhất ${last?last.toLocaleDateString("vi-VN"):"—"}.`;
288	  $("nDv").textContent=U.length;$("nVm").textContent=o.length;$("nNc").textContent=S.nhomchat.length;$("nNg").textContent=S.nguoi.reduce((a,g)=>a+g.nguoi.length,0)||"";$("nTl").textContent=S.tailieu.reduce((a,g)=>a+(g.muc||[]).length,0)||"";
289	}
290	function rUnits(){
291	  const sel=$("fDvSt");if(sel.options.length<2)sel.innerHTML+=ST.map(s=>`<option>${s}</option>`).join("");
292	  const q=norm($("qDv").value),f=sel.value;
293	  const U=units().filter(u=>(!f||u.dt===f||u.ndc===f)&&(!q||norm(u.ten+" "+u.ba+" "+u.rs.map(r=>Object.values(r).join(" ")).join(" ")).includes(q)));
294	  $("dvGroups").innerHTML=CATORDER.filter(c=>U.some(u=>u.cat===c)).map(c=>{const us=U.filter(u=>u.cat===c);return `<div class="card"><div class="grp"><h3>${CAT[c]||c}</h3><span>${us.length} đơn vị</span></div><div class="tbl"><table><thead><tr><th style="width:22%">Đơn vị</th><th>DevTest / 103NT</th><th>NDC</th><th style="width:38%">Đang vướng</th><th>BA</th></tr></thead><tbody>${us.map(u=>`<tr class="go" data-unit="${esc(u.ten)}"><td><div class="t">${esc(u.ten)}</div><div class="d">${u.rs.length} luồng</div></td><td>${pill(u.dt)}</td><td>${pill(u.ndc)}</td><td>${u.bl.length?`<div class="clamp">${esc(u.bl[0].blocker)}</div>${u.bl.length>1?`<div class="d">và ${u.bl.length-1} vướng mắc khác</div>`:""}`:`<span class="d">Không có</span>`}</td><td>${esc(u.ba)}</td></tr>`).join("")}</tbody></table></div></div>`}).join("")||`<div class="card empty">${S.loaded?"Không có đơn vị khớp bộ lọc.":"Đang tải…"}</div>`;
295	}
296	function seg(id,opts,cur,on){$(id).innerHTML=opts.map(([v,l])=>`<button type="button" aria-pressed="${v===cur}" data-v="${esc(v)}">${esc(l)}</button>`).join("");$(id).onclick=e=>{const b=e.target.closest("button");if(b)on(b.dataset.v)}}
297	function rBlock(){
298	  const o=S.luong.filter(open);const cnt=k=>o.filter(r=>owners(r).includes(k)).length;
299	  seg("segOwn",[["",`Tất cả (${o.length})`],["Nội bộ NADAT",`Nội bộ NADAT (${cnt("Nội bộ NADAT")})`],["C12 / hạ tầng",`C12 / hạ tầng (${cnt("C12 / hạ tầng")})`],["Đối tác",`Đối tác (${cnt("Đối tác")})`]],S.own,v=>{S.own=v;rBlock()});
300	  const rows=o.filter(r=>!S.own||owners(r).includes(S.own)).map(r=>({r,d:days(bDate(r))})).sort((a,b)=>(b.d??-1)-(a.d??-1));
301	  $("tbBlock").innerHTML=rows.map(({r,d})=>`<tr class="go" data-luong="${esc(r._id)}"><td class="num ${d>=14?"hot":""}">${d??"?"}</td><td><div class="t">${esc(dvOf(r))}</div><div class="d">${esc(r.ma)}</div></td><td>${esc(r.blocker)}<div class="d">${esc(r.loai)}</div></td><td>${owners(r).map(ownTag).join(" ")||esc(r.blocker_thuoc)}</td><td class="d">${esc(r.ai_chan)}</td><td>${esc(r.viec_tiep)}<div class="d">${esc(r.nguoi_lam)}</div></td></tr>`).join("")||`<tr><td colspan="6" class="empty">${S.loaded?"Không có vướng mắc.":"Đang tải…"}</td></tr>`;
302	}
303	function personRows(ps){return ps.map(p=>`<tr><td><div class="t">${esc(p.ho_ten)}</div></td><td class="d">${esc(p.tai_khoan)||"—"}</td><td>${esc(p.phong_ban)||`<span class="d">chưa rõ</span>`}</td><td class="d">${esc(p.vai_tro)}</td><td class="d">${esc(p.nhom_chat)}</td></tr>`).join("")}
304	function rPeople(){
305	  const B=["Nội bộ NADAT","Chủ đầu tư – C12","Nhà thầu, hệ thống trong NDC","Bộ, ngành","Địa phương","Doanh nghiệp","Chưa rõ đơn vị"];
306	  const cnt=b=>S.nguoi.filter(g=>g.ben===b).reduce((a,g)=>a+g.nguoi.length,0);
307	  seg("segBen",[["","Tất cả"],...B.map(b=>[b,`${b} (${cnt(b)})`])],S.ben,v=>{S.ben=v;rPeople()});
308	  const q=norm($("qNg").value);
309	  const gs=S.nguoi.filter(g=>!S.ben||g.ben===S.ben).sort((a,b)=>B.indexOf(a.ben)-B.indexOf(b.ben)).map(g=>({g,ps:g.nguoi.filter(p=>!q||norm(g.dv+" "+Object.values(p).join(" ")).includes(q))})).filter(x=>x.ps.length);
310	  $("ngGroups").innerHTML=gs.map(({g,ps})=>`<div class="card"><div class="grp"><h3>${esc(g.dv)}</h3><span>${ownTagBen(g.ben)} · ${ps.length} người</span></div><div class="tbl"><table><thead><tr><th style="width:24%">Họ tên</th><th style="width:18%">Tài khoản chat</th><th style="width:18%">Phòng ban</th><th>Vai trò</th><th style="width:20%">Nhóm chat</th></tr></thead><tbody>${personRows(ps)}</tbody></table></div></div>`).join("")||`<div class="card empty">${S.loaded?"Không có người khớp.":"Đang tải…"}</div>`;
311	}
312	const ownTagBen=b=>`<span class="tag ${b.startsWith("Nội")?"in":b.includes("C12")?"c12":b.startsWith("Chưa")?"":"ext"}">${esc(b)}</span>`;
313	function rChat(){
314	  const q=norm($("qChat").value),p=$("fPlat").value;
315	  const rows=S.nhomchat.filter(r=>(!p||r.nen_tang===p)&&(!q||norm(Object.values(r).join(" ")).includes(q)));
316	  $("tbChat").innerHTML=rows.map(r=>`<tr><td><span class="tag">${esc(r.nen_tang)}</span></td><td class="t">${esc(r.ten)}</td><td class="d">${esc(r.ma_luong)}</td><td>${esc(r.ba)}</td><td>${/KHÔNG|CHƯA/.test(r.doc_cuoi)?`<span class="pill p-block">${esc(r.doc_cuoi)}</span>`:esc(r.doc_cuoi)}<div class="d">tin mới nhất ${esc(r.tin_moi)}</div></td><td class="d"><div class="clamp" title="${esc(r.ghi_chu)}">${esc(r.ghi_chu)}</div></td></tr>`).join("")||`<tr><td colspan="6" class="empty">${S.loaded?"Không có nhóm khớp.":"Đang tải…"}</td></tr>`;
317	}
318	function docRow(m){const web=/^https?:/.test(m.duong_dan);return `<tr><td title="${esc(m.duong_dan)}"><div class="t c1">${web?`<a href="${esc(m.duong_dan)}">${esc(m.ten)}</a>`:esc(m.ten)}</div>${m.mo_ta?`<div class="d c1" title="${esc(m.mo_ta)}">${esc(m.mo_ta)}</div>`:""}</td><td><span class="tag">${esc(m.loai)}</span></td><td class="d"><div class="c1" title="${esc(m.nguon)}">${esc(m.nguon)}</div>${esc(m.ngay)}</td><td>${/Chưa|Không/.test(m.trang_thai)?`<span class="pill p-wait">${esc(m.trang_thai)}</span>`:/Đang/.test(m.trang_thai)?`<span class="pill p-run">${esc(m.trang_thai)}</span>`:`<span class="pill p-ok">${esc(m.trang_thai||"Có sẵn")}</span>`}</td><td>${m.duong_dan&&!web?`<button class="btn sm" type="button" data-copy="${esc(m.duong_dan)}">Chép</button>`:""}</td></tr>`}
319	function rDocs(){
320	  const q=norm($("qTl").value);
321	  $("tlGroups").innerHTML=[...S.tailieu].sort((a,b)=>(a.thu_tu||9)-(b.thu_tu||9)).map(g=>{const ms=(g.muc||[]).filter(m=>!q||norm(Object.values(m).join(" ")).includes(q));return ms.length?`<div class="card"><div class="grp"><h3>${esc(g.ten)}</h3><span>${ms.length} mục</span></div><div class="tbl"><table><thead><tr><th style="width:46%">Tài liệu</th><th>Loại</th><th>Nguồn</th><th>Trạng thái</th><th></th></tr></thead><tbody>${ms.map(docRow).join("")}</tbody></table></div></div>`:""}).join("")||`<div class="card empty">${S.loaded?"Chưa có tài liệu khớp.":"Đang tải…"}</div>`;
322	}
323	function rScan(){
324	  const q=S.quet,b=$("scanBtn");const tm=s=>s?new Date(s).toLocaleString("vi-VN",{hour:"2-digit",minute:"2-digit",day:"2-digit",month:"2-digit"}):"";
325	  let t="Chưa có lần quét nào.",busy=false;
326	  if(q){if(q.trang_thai==="cho"){busy=true;t=`Đã ghi yêu cầu lúc ${tm(q.yeu_cau_luc)}. Để bắt đầu quét: mở ứng dụng Claude, mục Scheduled, chọn tác vụ "Quét chat NDOP" rồi bấm Run now.`}
327	    else if(q.trang_thai==="dang_chay"){busy=true;t=`Đang quét các nhóm chat, bắt đầu lúc ${tm(q.bat_dau)}.`}

328	    else t=`Lần quét gần nhất: ${tm(q.ket_thuc)}. ${q.tom_tat||""}`}
329	  $("scanText").textContent=t;b.disabled=busy||!S.db||S.canWrite===false;b.textContent=busy?"Đã ghi yêu cầu":"Ghi yêu cầu quét";
330	}
331	function rAll(){rOverview();rUnits();rBlock();rPeople();rChat();rDocs();rScan();if(S.unit&&!S.edit)showUnit(S.unit)}
332	
333	/* ---------- Ngăn chi tiết ---------- */
334	function openD(){$("scrim").hidden=false;$("drawer").hidden=false}
335	function closeD(){S.unit=null;S.edit=null;$("scrim").hidden=true;$("drawer").hidden=true}
