  showForm("Thêm luồng đấu nối","Sau khi tạo, mở đơn vị để nhập trạng thái và vướng mắc.",[{k:"ma",l:"Mã luồng (ví dụ CS-18)",v:""},{k:"dv",l:"Đơn vị",v:"",list:"dlDv"},{k:"nhom",l:"Nhóm đơn vị",o:CATORDER.map(c=>CAT[c]),v:CAT.BBN},{k:"luong",l:"Tên luồng",v:""},{k:"nv",l:"Nghiệp vụ",o:["CS","TH","ĐP","TH + ĐP"],v:"CS"},{k:"ba",l:"BA phụ trách",v:""}],
  async v=>{if(!v.ma||!v.dv){toast("Cần nhập mã luồng và đơn vị.");return false}const id=norm(v.ma).replace(/[^a-z0-9]+/g,"-");if(S.luong.some(r=>r._id===id)){toast("Mã luồng này đã có.");return false}
    const d=new Date(),p2=n=>String(n).padStart(2,"0");await S.db.collection("luong").doc(id).set({ma:v.ma,dv:v.dv,donvi:v.dv,nhom:CATORDER.find(c=>CAT[c]===v.nhom)||"BBN",luong:v.luong,nv:v.nv,ba:v.ba,dev:"",dt_tt:"Chưa bắt đầu",dt_buoc:"",ndc_tt:"Chưa bắt đầu",ndc_buoc:"",blocker:"",blocker_thuoc:"",loai:"",ai_chan:"",viec_tiep:"",nguoi_lam:"",nhom_chat:"",cap_nhat:`${p2(d.getDate())}/${p2(d.getMonth()+1)}/${d.getFullYear()}`})});
}
[["v-don-vi","luong","Thêm luồng"],["v-nguoi","ng","Thêm người"],["v-nhom-chat","nc","Thêm nhóm"],["v-tai-lieu","tl","Thêm tài liệu"]].forEach(([s,k,l])=>document.querySelector("#"+s+" .head").insertAdjacentHTML("beforeend",`<button class="btn primary" type="button" data-add="${k}">${l}</button>`));
document.addEventListener("click",e=>{
  if(e.target.closest("[data-copy]")||e.target.closest("aside"))return;
  const a=e.target.closest("[data-add]");if(a){({luong:addFlow,ng:()=>editPerson("",-1),nc:()=>editChat(""),tl:()=>editDoc("",-1)})[a.dataset.add]();return}
  let t=e.target.closest("[data-ng]");if(t){const [g,i]=t.dataset.ng.split("|");editPerson(g,+i);return}
  t=e.target.closest("[data-nc]");if(t){editChat(t.dataset.nc);return}
  t=e.target.closest("[data-tl]");if(t){const [g,i]=t.dataset.tl.split("|");editDoc(g,+i)}});


/* ---------- Hạn xử lý, Việc của tôi ---------- */
S.momang=[];S.mm="";
const dueOf=r=>pDate(r.han_xu_ly);
const lateDays=r=>{const d=dueOf(r);if(!d)return null;const t=new Date();t.setHours(0,0,0,0);return Math.round((t-d)/864e5)};
function names(){const set=new Set();S.luong.forEach(r=>[r.ba,r.nguoi_lam].forEach(v=>String(v||"").split(/[,/;+()]|\s–\s/).map(x=>x.replace(/theo dõi:|^A |^anh |^chị /i,"").trim()).filter(x=>x&&x.length>1&&x.length<24&&x!=="—").forEach(x=>set.add(x))));return [...set].sort((a,b)=>a.localeCompare(b,"vi"))}
function rMe(){
  const sel=$("fMe"),ns=names();let cur=sel.value;if(!cur){try{cur=localStorage.getItem("ndop_me")||""}catch(e){}}
  sel.innerHTML=`<option value="">Chọn tên…</option>`+ns.map(n=>`<option ${n===cur?"selected":""}>${esc(n)}</option>`).join("");
  const me=sel.value,only=$("fOnlyLate").checked;
  const mine=me?S.luong.filter(r=>norm(r.ba).includes(norm(me))||norm(r.nguoi_lam).includes(norm(me))):[];
  const rows=mine.filter(r=>!only||lateDays(r)===null||lateDays(r)>0).sort((a,b)=>(dueOf(a)||9e15)-(dueOf(b)||9e15));
  const late=mine.filter(r=>lateDays(r)>0).length,nodue=mine.filter(r=>!dueOf(r)).length,soon=mine.filter(r=>{const l=lateDays(r);return l!==null&&l<=0&&l>=-3}).length;
  $("meKpi").innerHTML=me?[["Việc của bạn",mine.length,""],["Quá hạn",late,late?"warn":""],["Đến hạn trong 3 ngày",soon,""],["Chưa đặt hạn",nodue,nodue?"warn":""]].map(([l,v,c])=>`<div class="card kpi ${c}"><div class="l">${l}</div><div class="v">${v}</div></div>`).join(""):"";
  $("tbMe").innerHTML=!me?`<tr><td colspan="5" class="empty">Chọn tên của bạn ở ô phía trên.</td></tr>`:rows.map(r=>{const l=lateDays(r);return `<tr class="go" data-luong="${esc(r._id)}"><td class="num ${l>0?"hot":""}">${r.han_xu_ly?esc(r.han_xu_ly)+(l>0?`<div class="d">quá ${l} ngày</div>`:l===0?`<div class="d">hôm nay</div>`:""):`<span class="d">chưa đặt</span>`}</td><td><div class="t">${esc(dvOf(r))}</div><div class="d">${esc(r.ma)}</div></td><td>${esc(r.viec_tiep)}</td><td class="d">${open(r)?esc(r.blocker):"—"}</td><td class="d">${norm(r.nguoi_lam).includes(norm(me))?"Người làm tiếp":"BA phụ trách"}</td></tr>`}).join("")||`<tr><td colspan="5" class="empty">Không có việc nào.</td></tr>`;
  const allLate=S.luong.filter(r=>lateDays(r)>0).length;$("nQh").textContent=allLate||"";
}
$("fMe").addEventListener("input",()=>{try{localStorage.setItem("ndop_me",$("fMe").value)}catch(e){}rMe()});$("fOnlyLate").addEventListener("input",rMe);

/* ---------- Mở mạng NDC ---------- */
const MMST={phieu:["Chưa gửi","Đã gửi"],p5:["Chưa duyệt","Đã duyệt","Trả lại"],gtel:["Chưa mở","Đã mở","Mở một phần"],kt:["Chưa kiểm tra","Đã thông","Lỗi"]};
function mmWait(m){if(!m.ip_nguon||!m.ip_dich||!m.cong)return "Thiếu bảng luồng (BA, Dev, đối tác)";if(m.phieu!=="Đã gửi")return "Chưa gửi phiếu (NADAT)";if(m.p5!=="Đã duyệt")return "Chờ P5 C12 duyệt";if(m.gtel!=="Đã mở")return "Chờ Gtel mở";if(m.kt!=="Đã thông")return m.kt==="Lỗi"?"Lỗi kết nối – Dev, hạ tầng":"Chờ kiểm tra thông";return "Xong"}
const mmPill=(v,okv)=>`<span class="pill p-${v===okv?"ok":/Lỗi|Trả lại/.test(v||"")?"block":/Đã gửi|một phần/.test(v||"")?"run":"wait"}">${esc(v||"—")}</span>`;
function rMm(){
  const st=m=>mmWait(m);const cnt=k=>S.momang.filter(m=>k===""?true:k==="xong"?st(m)==="Xong":st(m)!=="Xong").length;
  seg("segMm",[["",`Tất cả (${cnt("")})`],["mo",`Chưa xong (${cnt("mo")})`],["xong",`Đã thông (${cnt("xong")})`]],S.mm,v=>{S.mm=v;rMm()});
  const rows=S.momang.filter(m=>!S.mm||(S.mm==="xong"?st(m)==="Xong":st(m)!=="Xong")).sort((a,b)=>String(a.don_vi).localeCompare(String(b.don_vi),"vi"));
  $("tbMm").innerHTML=rows.map(m=>`<tr class="go" data-mm="${esc(m._id)}"><td><div class="t">${esc(m.don_vi)}</div><div class="d">${esc(m.ma_luong)}</div></td><td class="d">${esc(m.chieu)}</td><td class="d">${m.ip_nguon||m.ip_dich?`${esc(m.ip_nguon||"?")} → ${esc(m.ip_dich||"?")}<div>cổng ${esc(m.cong||"?")}</div>`:`<span class="pill p-block">Chưa có</span>`}</td><td>${mmPill(m.phieu,"Đã gửi")}<div class="d">${esc(m.ngay_phieu||"")}</div></td><td>${mmPill(m.p5,"Đã duyệt")}</td><td>${mmPill(m.gtel,"Đã mở")}</td><td>${mmPill(m.kt,"Đã thông")}</td><td>${esc(st(m))}<div class="d">${esc(m.ghi_chu||"")}</div></td></tr>`).join("")||`<tr><td colspan="8" class="empty">${S.loaded?"Chưa có luồng mở mạng nào.":"Đang tải…"}</td></tr>`;
  $("nMm").textContent=cnt("mo")||"";
}
function editMm(id){
  const m=S.momang.find(x=>x._id===id)||{};
  showForm(m.don_vi?`Mở mạng · ${m.don_vi}`:"Thêm luồng mở mạng","",[{k:"don_vi",l:"Đơn vị",v:m.don_vi,list:"dlDv"},{k:"ma_luong",l:"Mã luồng",v:m.ma_luong},{k:"chieu",l:"Chiều kết nối (ví dụ NDOP DMZ → AGN MoMo)",v:m.chieu},{k:"ip_nguon",l:"IP nguồn",v:m.ip_nguon},{k:"ip_dich",l:"IP đích",v:m.ip_dich},{k:"cong",l:"Cổng (port)",v:m.cong},{k:"phieu",l:"Phiếu mở mạng",o:MMST.phieu,v:m.phieu||"Chưa gửi"},{k:"ngay_phieu",l:"Ngày gửi phiếu",v:m.ngay_phieu},{k:"p5",l:"P5 C12 duyệt",o:MMST.p5,v:m.p5||"Chưa duyệt"},{k:"gtel",l:"Gtel mở",o:MMST.gtel,v:m.gtel||"Chưa mở"},{k:"kt",l:"Kiểm tra kết nối",o:MMST.kt,v:m.kt||"Chưa kiểm tra"},{k:"ghi_chu",l:"Ghi chú, căn cứ",v:m.ghi_chu,t:"area"}],
  async v=>{if(!v.don_vi){toast("Cần nhập đơn vị.");return false}const d=new Date(),p2=n=>String(n).padStart(2,"0");v.cap_nhat=`${p2(d.getDate())}/${p2(d.getMonth()+1)}/${d.getFullYear()}`;const c=S.db.collection("momang");if(m._id)await c.doc(m._id).set(v);else await c.add(v)},
  m._id?()=>S.db.collection("momang").doc(m._id).delete():null);
}
document.querySelector("#v-mo-mang .head").insertAdjacentHTML("beforeend",`<button class="btn primary" type="button" id="mmAdd">Thêm luồng mở mạng</button>`);
$("mmAdd").onclick=()=>editMm("");
document.addEventListener("click",e=>{const t=e.target.closest("[data-mm]");if(t&&!e.target.closest("aside"))editMm(t.dataset.mm)});

/* ---------- Báo cáo tuần ---------- */
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
{const t=new Date(),f=new Date(t-6*864e5);$("bcFrom").value=iso(f);$("bcTo").value=iso(t)}
function rBc(){
  const f=new Date($("bcFrom").value+"T00:00:00"),t=new Date($("bcTo").value+"T23:59:59");if(isNaN(f)||isNaN(t))return;
  const inR=d=>d&&d>=f&&d<=t,vn=d=>d.toLocaleDateString("vi-VN"),U=units(),o=S.luong.filter(open);
  const upd=S.luong.filter(r=>inR(pDate(r.cap_nhat))).sort((a,b)=>String(dvOf(a)).localeCompare(String(dvOf(b)),"vi"));
  const nk=S.nhatky.filter(x=>inR(new Date(x.at)));
  const moved=[],cleared=[];nk.forEach(x=>(x.thay_doi||[]).forEach(c=>{const r=S.luong.find(y=>y._id===x.luong);const n=r?`${dvOf(r)} (${r.ma})`:x.luong;if(/_tt$/.test(c.truong))moved.push(`${n}: ${c.truong==="ndc_tt"?"NDC":"DevTest/103NT"} ${c.cu||"—"} → ${c.moi}`);if(c.truong==="blocker"&&(!c.moi||c.moi==="—")&&c.cu&&c.cu!=="—")cleared.push(`${n}: ${c.cu}`)}));
  const newB=o.filter(r=>inR(bDate(r))),late=S.luong.filter(r=>lateDays(r)>0),mmOpen=S.momang.filter(m=>mmWait(m)!=="Xong");
  const own=k=>o.filter(r=>owners(r).includes(k)).length;
  const L=[];
  L.push(`BÁO CÁO TIẾN ĐỘ ĐẤU NỐI NDOP`,`Kỳ báo cáo: ${vn(f)} – ${vn(t)}`,"");
  L.push("1. Tổng quan",`- ${U.length} đơn vị, hệ thống; ${S.luong.length} luồng đấu nối.`,`- Xong DevTest/103NT: ${U.filter(u=>u.dt==="Hoàn thành").length} đơn vị. Xong NDC: ${U.filter(u=>u.ndc==="Hoàn thành").length} đơn vị.`,`- Đang bị chặn: ${U.filter(u=>u.dt==="Bị block"||u.ndc==="Bị block").length} đơn vị. Vướng mắc đang mở: ${o.length} (nội bộ NADAT ${own("Nội bộ NADAT")}, C12/hạ tầng ${own("C12 / hạ tầng")}, đối tác ${own("Đối tác")}).`,"");
  L.push(`2. Chuyển trạng thái trong kỳ (${moved.length})`,...(moved.length?moved.map(x=>"- "+x):["- Không có thay đổi trạng thái được ghi trên trang."]),"");
  L.push(`3. Luồng có cập nhật trong kỳ (${upd.length})`,...(upd.length?upd.map(r=>`- ${dvOf(r)} (${r.ma}) – DevTest/103NT: ${stOf(r.dt_tt)}; NDC: ${stOf(r.ndc_tt)}. Tiếp theo: ${r.viec_tiep||"—"}`):["- Không có."]),"");
  L.push(`4. Vướng mắc mới phát sinh (${newB.length})`,...(newB.length?newB.map(r=>`- ${dvOf(r)} (${r.ma}): ${r.blocker} – đang chặn: ${r.ai_chan||"—"}`):["- Không có."]),"");
  L.push(`5. Vướng mắc đã gỡ (${cleared.length})`,...(cleared.length?cleared.map(x=>"- "+x):["- Chưa ghi nhận trên trang."]),"");
  L.push(`6. Việc quá hạn (${late.length})`,...(late.length?late.map(r=>`- ${dvOf(r)} (${r.ma}): ${r.viec_tiep||"—"} – ${r.nguoi_lam||r.ba||"chưa giao"}, hạn ${r.han_xu_ly}`):["- Không có (hoặc chưa đặt hạn)."]),"");
  L.push(`7. Mở mạng NDC chưa xong (${mmOpen.length})`,...(mmOpen.length?mmOpen.map(m=>`- ${m.don_vi}: ${m.chieu||""} – ${mmWait(m)}`):["- Không có."]),"");
  const top=o.map(r=>({r,d:days(bDate(r))})).sort((a,b)=>(b.d??-1)-(a.d??-1)).slice(0,5);
  L.push("8. Đề nghị hỗ trợ (vướng lâu nhất)",...top.map(({r,d})=>`- ${dvOf(r)} (${r.ma}, ${d??"?"} ngày): ${r.blocker} – đề nghị ${r.ai_chan||"các bên"} xử lý.`));
  $("bcText").textContent=L.join("\n");
}
["bcFrom","bcTo"].forEach(i=>$(i).addEventListener("input",rBc));
$("bcCopy").onclick=async()=>{const txt=$("bcText").textContent;try{await navigator.clipboard.writeText(txt);toast("Đã chép báo cáo.")}catch(e){const r=document.createRange();r.selectNodeContents($("bcText"));const s=getSelection();s.removeAllRanges();s.addRange(r);toast("Đã bôi đen báo cáo, bấm Ctrl+C để chép.")}};
{const a0=rAll;rAll=function(){a0();rMe();rMm();rBc()}}

/* ---------- Dữ liệu ---------- */
rAll();
const sync=(live,t)=>{$("dot").className="dot"+(live?" live":"");$("synctext").textContent=t};
(async()=>{
  const timer=setTimeout(()=>{if(!S.loaded)sync(false,"Chưa kết nối được dữ liệu. Tải lại trang để thử lại.")},10000);
  const c=window.claude,db=c&&c.use?await c.use("db"):null;S.user=c&&c.use?await c.use("user"):null;
  try{S.canWrite=S.user?await S.user.can("data.write"):null}catch(e){}
  if(!db){clearTimeout(timer);sync(false,"Cần đăng nhập claude.ai để xem dữ liệu.");S.loaded=true;rAll();return}
  S.db=db;
  ["luong","nhomchat","nguoi","tailieu","nhatky","momang"].forEach(col=>db.collection(col).onSnapshot(s=>{
    S[col]=s.docs.map(d=>Object.assign({_id:d.id},d.data()));
    if(col==="luong"){S.luong.sort((a,b)=>String(a.ma).localeCompare(String(b.ma),"vi",{numeric:true}));S.loaded=true;clearTimeout(timer);sync(true,"Dữ liệu đang đồng bộ")}
    rAll();if(S.edit&&col==="nhatky")hist()},()=>{clearTimeout(timer);sync(false,"Mất kết nối dữ liệu. Tải lại trang.")}));
  db.doc("yeucau/quet").onSnapshot(d=>{S.quet=d.data()||null;rScan()},()=>{});
})();
</script>

