.sq.ok{background:var(--ok-bg);color:var(--ok)}.sq.run{background:var(--run-bg);color:var(--run)}.sq.wait{background:var(--wait-bg);color:var(--wait)}.sq.block{background:var(--block);color:#fff;border-color:var(--block)}.sq.pend,.sq.none{background:var(--surface);color:var(--mute)}
.legend{display:flex;flex-wrap:wrap;gap:10px;font-size:12px;color:var(--ink-2);align-items:center}
.legend span{display:inline-flex;gap:4px;align-items:center}
.stale{display:inline-block;font-size:11px;line-height:16px;font-weight:700;padding:0 5px;border-radius:4px;background:var(--mute);color:#fff;white-space:nowrap}
.flag{display:inline-block;font-size:11px;line-height:16px;font-weight:700;padding:0 5px;border-radius:4px;background:var(--block);color:#fff;white-space:nowrap}
.warnchip{display:inline-block;font-size:11px;line-height:16px;font-weight:700;padding:0 5px;border-radius:4px;background:var(--wait-bg);color:var(--wait);border:1px solid var(--wait);white-space:nowrap}
tr.cat td{background:var(--ink);color:#fff;font-weight:700;font-size:12px;letter-spacing:.04em;text-transform:uppercase;padding:4px 10px}
tr.open-row{background:var(--hover)!important}
tr.xrow>td{background:#f7f9fc;padding:0;border-bottom:2px solid var(--ink)}
.xin{padding:10px 14px;display:grid;gap:10px}
.tabs{display:flex;gap:2px;border-bottom:2px solid var(--line)}
.tabs button{border:0;background:none;padding:6px 12px;font:600 13px/18px var(--font);color:var(--ink-2);cursor:pointer;border-bottom:3px solid transparent;margin-bottom:-2px}
.tabs button[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--brand)}
.fl{border:1px solid var(--line);border-radius:var(--r);background:var(--surface);padding:8px 10px;display:grid;gap:6px}
.fl .top{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap}
.fl dl{display:grid;grid-template-columns:110px 1fr;gap:3px 10px;margin:0;font-size:13px}
.fl dt{color:var(--ink-3);font-weight:600}.fl dd{margin:0;min-width:0}
.chk{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:13px}
.chk label{display:inline-flex;gap:5px;align-items:center;cursor:pointer}
.chk input{width:16px;height:16px;accent-color:var(--brand)}
.left td{color:var(--ink-3)}.left td.t{text-decoration:none}
.twocol{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,440px),1fr));gap:12px}
.kanban{display:grid;grid-template-columns:repeat(6,minmax(170px,1fr));gap:8px;overflow-x:auto;padding-bottom:4px}
.kcol{background:var(--mute-bg);border:1px solid var(--line);border-radius:var(--r);display:flex;flex-direction:column;min-height:160px}
.kcol h4{margin:0;padding:6px 8px;font-size:12px;line-height:16px;font-weight:700;border-bottom:2px solid var(--ink);display:flex;justify-content:space-between;gap:6px}
.kcol.over{outline:3px dashed var(--brand);outline-offset:-3px}
.klist{padding:6px;display:grid;gap:6px;align-content:start;flex:1}
.kc{background:var(--surface);border:1.5px solid var(--line);border-radius:var(--r);padding:6px 8px;cursor:grab;display:grid;gap:3px;font-size:12.5px;line-height:17px}
.kc.late{border-color:var(--block);border-width:2px}
.kc .t{font-size:13px}
.kc .row{display:flex;justify-content:space-between;align-items:center;gap:6px}
.dx{display:grid;gap:0}
.dx .it{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;padding:8px 14px;border-top:1px solid var(--line);align-items:start}
.dx .it .acts{display:flex;gap:6px}
.old{text-decoration:line-through;color:var(--ink-3)}
@media (max-width:860px){.filters{margin-top:0}.fl dl{grid-template-columns:1fr}}

