    <dl><dt>DevTest/103NT</dt><dd>${pill(r.dt_tt)} ${r.bbnt_dt?`<span class="tag in" title="${esc(r.bbnt_dt)}">BBNT đã gắn</span>`:stOf(r.dt_tt)==="Hoàn thành"?`<span class="warnchip">Thiếu BBNT</span>`:""} <span class="d">${esc(r.dt_buoc)}</span></dd>
