     ('lỗi 500 do bắt tay bảo mật (TLS) tới máy TTTT dev thất bại', 'lỗi 500 TLS handshake failure tới TTTT dev'), ('Lỗi TLS khi', 'Lỗi TLS handshake khi'),
     ('kịch bản kiểm thử', 'testcase'), ('bộ nhập dữ liệu (Data Importer)', 'Data Importer'), ('đường thuê riêng', 'leased line'),
     ('xử lý chứng thư/TLS máy dev', 'xử lý certificate/TLS trên TTTT dev'), ('lỗi phân giải tên miền', 'lỗi DNS'), ('không phân giải tên miền', 'lỗi DNS'),
     ('(kết nối giữa các ShareNode)', '(peer giữa các ShareNode)'), ('Nicolas Nguyen duyệt format', 'anh Quang/Nicolas duyệt format'), ('Chị Trà / Nicolas Nguyen', 'Chị Trà / A Quang (Nicolas)')]
def fix(o):
    if isinstance(o, str):
        for a, b in R: o = o.replace(a, b)
        return o
    if isinstance(o, list): return [fix(x) for x in o]
    if isinstance(o, dict): return {k: fix(v) for k, v in o.items()}
    return o
W = []; os.makedirs(S + '/v10/out', exist_ok=True)
for col in ('luong', 'momang', 'nhomchat', 'tailieu'):
    for f in glob.glob(f'{S}/db5/{col}/*.json'):
        i = os.path.basename(f)[:-5]; d = json.load(open(f, encoding='utf-8')); n = fix(d)
        if n != d:
            if col == 'tailieu':
                p = f'{S}/v10/out/tl_{i}.json'; json.dump(n, open(p, 'w', encoding='utf-8'), ensure_ascii=False)
                W.append({'op': 'set', 'collection': col, 'doc_id': i, 'file_path': p, 'if_version': VER[col][i]})
            else:
                ch = {k: v for k, v in n.items() if v != d.get(k)}
                W.append({'op': 'update', 'collection': col, 'doc_id': i, 'if_version': VER[col][i], 'data': ch})
W.append({'op': 'set', 'collection': 'nguoi', 'doc_id': 's00', 'file_path': S + '/gop3/nguoi_s00_v3.json', 'if_version': 2})
json.dump(W, open(S + '/v10/batch.json', 'w', encoding='utf-8'), ensure_ascii=False)
for w in W: print(w['collection'], w['doc_id'], w.get('if_version'), json.dumps(w.get('data', ''), ensure_ascii=False)[:160])

