rep('async v=>{if(!v.ma||!v.dv){toast("Cần nhập mã luồng và đơn vị.");return false}const id=',
    'async v=>{if(!v.ma||!v.dv||!v.luong||!v.ba){toast("Cần nhập đủ các ô có dấu *.");return false}const id=')
# editPerson prefill
rep('function editPerson(gid,idx){\n  const g=S.nguoi.find(x=>x._id===gid),p=g&&idx>=0?g.nguoi[idx]:{};',
    'function editPerson(gid,idx,pre){pre=pre||{};\n  const g=S.nguoi.find(x=>x._id===gid)||S.nguoi.find(x=>pre.dv&&x.dv===pre.dv),p=gid&&g&&idx>=0?g.nguoi[idx]:{};if(!gid)idx=-1;')
rep('{k:"dv",l:"Đơn vị",v:g?g.dv:"",list:"dlDv"},{k:"ben",l:"Thuộc bên",o:BENS,v:g?g.ben:"Chưa rõ đơn vị"}',
