rep('{k:"ho_ten",l:"Họ tên",v:p.ho_ten}','{k:"ho_ten",l:"Họ tên *",v:p.ho_ten}')
# editDoc prefill + don_vi
rep('function editDoc(gid,idx){\n  const g=S.tailieu.find(x=>x._id===gid)||S.tailieu[0],m=g&&idx>=0?g.muc[idx]:{};if(!g)return;',
    'function editDoc(gid,idx,pre){pre=pre||{};\n  const g=S.tailieu.find(x=>x._id===gid)||S.tailieu.find(x=>x._id==="chat")||S.tailieu[0],m=g&&idx>=0?g.muc[idx]:Object.assign({},pre);if(!g)return;')
rep('{k:"ten",l:"Tên tài liệu",v:m.ten},{k:"loai",l:"Loại",v:m.loai}','{k:"ten",l:"Tên tài liệu *",v:m.ten},{k:"don_vi",l:"Thuộc đơn vị",v:m.don_vi,list:"dlUnit"},{k:"loai",l:"Loại",o:["","API spec","BBNT","Biên bản họp","Phiếu Firewall","Hướng dẫn, runbook","Testcase","Công văn","Báo cáo","Biểu mẫu","Mô hình, sơ đồ","Khác",...(m.loai&&!["API spec","BBNT","Biên bản họp","Phiếu Firewall","Hướng dẫn, runbook","Testcase","Công văn","Báo cáo","Biểu mẫu","Mô hình, sơ đồ","Khác"].includes(m.loai)?[m.loai]:[])],v:m.loai||""}')
rep('const it={ten:v.ten,loai:v.loai,duong_dan:v.duong_dan,mo_ta:v.mo_ta,nguon:v.nguon,ngay:v.ngay,trang_thai:v.trang_thai};',
    'const it=Object.assign({},m,{ten:v.ten,don_vi:v.don_vi,loai:v.loai,duong_dan:v.duong_dan,mo_ta:v.mo_ta,nguon:v.nguon,ngay:v.ngay,trang_thai:v.trang_thai});')
# unitAdd + helpers
rep('/* ---------- Stakeholder ---------- */','''const BEN_OF={"BBN":"Bộ, ngành","ĐP":"Địa phương","HTPM":"Nhà thầu, hệ thống trong NDC","DN":"Doanh nghiệp","Nội bộ NDC":"Nội bộ NADAT"};
function unitAdd(k,un){const u=units(S.luong).find(x=>x.ten===un)||{ten:un,rs:[]},r0=u.rs[0]||{};
  if(k==="luong")addFlow({dv:un,nhom:u.cat,ba:baNames(r0)[0]||""});
  else if(k==="nguoi"){const keys=PEOPLE_OF[un]||[un],g=S.nguoi.find(x=>keys.includes(x.dv));editPerson("",-1,{dv:g?g.dv:un,ben:g?g.ben:BEN_OF[u.cat]||"Chưa rõ đơn vị"})}
  else if(k==="chat")editChat("",{don_vi:un,ma_luong:u.rs.map(r=>r.ma).join(", "),ba:baNames(r0).join(", ")});
  else editDoc("",-1,{don_vi:un,trang_thai:"Có sẵn"})}
