$GRAPHIFY_PYTHON = $null
function Find-GraphifyPython {
    if (Get-Command uv -ErrorAction SilentlyContinue) {
        $uvDir = (uv tool dir 2>$null)
        if ($uvDir) { $uvDir=$uvDir.Trim(); $py = Join-Path $uvDir "graphifyy\Scripts\python.exe"
            if (Test-Path $py) { & $py -c "import graphify" 2>$null; if ($LASTEXITCODE -eq 0) { return $py } } }
    }
    if (Get-Command pipx -ErrorAction SilentlyContinue) {
        $venvs = (pipx environment --value PIPX_LOCAL_VENVS 2>$null)
        if ($venvs) { $venvs=$venvs.Trim(); $py = Join-Path $venvs "graphifyy\Scripts\python.exe"
            if (Test-Path $py) { & $py -c "import graphify" 2>$null; if ($LASTEXITCODE -eq 0) { return $py } } }
    }
    $pyCmd = Get-Command python -ErrorAction SilentlyContinue
    if ($pyCmd) { & $pyCmd.Source -c "import graphify" 2>$null
        if ($LASTEXITCODE -eq 0) { return (& $pyCmd.Source -c "import sys; print(sys.executable)").Trim() } }
    return $null
}
$GRAPHIFY_PYTHON = Find-GraphifyPython
if (-not $GRAPHIFY_PYTHON) {
    if (Get-Command uv -ErrorAction SilentlyContinue) { uv tool install --upgrade graphifyy -q 2>&1 | Select-Object -Last 3 } else { pip install graphifyy -q 2>&1 | Select-Object -Last 3 }
    $GRAPHIFY_PYTHON = Find-GraphifyPython
}
$Utf8NoBom = New-Object System.Text.UTF8Encoding $false
[System.IO.File]::WriteAllText((Join-Path $PWD 'graphify-out\.graphify_python'), [string]$GRAPHIFY_PYTHON, $Utf8NoBom)
[System.IO.File]::WriteAllText((Join-Path $PWD 'graphify-out\.graphify_root'), (Resolve-Path '.').Path, $Utf8NoBom)
"PY=$GRAPHIFY_PYTHON"
@'
import json
from graphify.detect import detect
from pathlib import Path
from graphify.paths import out_path
from graphify.watch import _read_build_excludes, _read_build_gitignore
INPUT_PATH = Path('graphify-out/.graphify_root').read_text(encoding="utf-8-sig").strip()
