cd "C:/Users/admin/AppData/Local/Temp/claude/2be9bc1afaafe935/a3ee91ab-a830-4247-a1df-9badebb26daf/scratchpad/v10"; python -I - <<'EOF'
s=open('links.js',encoding='utf-8').read()
s=s.replace('// Chỉ lưu địa chỉ và tên tài khoản; KHÔNG lưu mật khẩu trên trang (trang chia sẻ cho nhiều người).',
'''// Địa chỉ + tên tài khoản: dữ liệu chung. Mật khẩu: lưu riêng từng người ở data/users/<id>/matkhau (người khác, kể cả chủ trang, không đọc được).
S.mk={};S.mkReady=false;S.mkShow=new Set();
async function mkInit(){if(!S.db||!S.user||S.mkRef)return;let uid=null;try{uid=await S.user.id()}catch(e){}if(!uid)return;
  S.mkRef=S.db.collection("data/users/"+uid).doc("matkhau");S.mkRef.onSnapshot(d=>{S.mk=(d&&d.data())||{};S.mkReady=true;rLinks()},()=>{S.mkReady=false;rLinks()})}
function mkCell(l){if(!S.mkReady)return `<span class="d">—</span>`;const v=S.mk[l._id];
  return v?`<div class="tools" style="flex-wrap:nowrap"><code class="mk">${S.mkShow.has(l._id)?esc(v):"••••••"}</code><button type="button" class="btn sm" data-mkshow="${esc(l._id)}">${S.mkShow.has(l._id)?"Ẩn":"Hiện"}</button><button type="button" class="btn sm" data-copy="${esc(v)}" data-quiet="1">Chép</button><button type="button" class="btn sm" data-mkedit="${esc(l._id)}" title="Sửa mật khẩu">Sửa</button></div>`:`<button type="button" class="btn sm" data-mkedit="${esc(l._id)}">+ Lưu mật khẩu</button>`}
function mkEdit(id){const l=S.lienket.find(x=>x._id===id);if(!l||!S.mkRef)return;S.edit=null;
  S.form={fields:[],onSave:async()=>{const v=$("g_mk").value;const next=Object.assign({},S.mk);if(v)next[id]=v;else delete next[id];await S.mkRef.set(next)}};
  $("dTitle").textContent="Mật khẩu · "+l.ten;$("dSub").textContent="Chỉ mình bạn thấy: lưu trong vùng riêng của tài khoản bạn, người khác mở trang (kể cả chủ trang) không đọc được.";$("dFoot").hidden=false;
  $("dBody").innerHTML=`<div class="fld"><label for="g_tk">Tài khoản</label><input id="g_tk" value="${esc(l.tai_khoan||"")}" disabled></div><div class="fld"><label for="g_mk">Mật khẩu</label><input id="g_mk" type="password" autocomplete="off" value="${esc(S.mk[id]||"")}"><span class="d">Để trống rồi lưu để xoá mật khẩu.</span></div><label class="d" style="display:flex;gap:6px;align-items:center"><input type="checkbox" id="g_mkv"> Hiện mật khẩu khi nhập</label>`;
  $("g_mkv").onchange=e=>$("g_mk").type=e.target.checked?"text":"password";$("dSave").disabled=false;$("dPerm").textContent="";openD();setTimeout(()=>$("g_mk").focus(),50)}''')
s=s.replace('<th style="width:16%">Tài khoản</th><th style="width:150px"></th>','<th style="width:14%">Tài khoản</th><th style="width:240px">Mật khẩu <span class="d">(chỉ bạn thấy)</span></th><th style="width:130px"></th>')
s=s.replace('''`<span class="d">—</span>`}</td><td><div class="tools" style="flex-wrap:nowrap">${h?''','''`<span class="d">—</span>`}</td><td>${mkCell(l)}</td><td><div class="tools" style="flex-wrap:nowrap">${h?''')
s=s.replace('function rLinks(){','function rLinks(){mkInit();')
s=s.replace('  if(e.target.closest("[data-copy]")||e.target.closest("a.btn"))return;','''  let m=e.target.closest("[data-mkshow]");if(m){const k=m.dataset.mkshow;S.mkShow.has(k)?S.mkShow.delete(k):S.mkShow.add(k);rLinks();return}
  m=e.target.closest("[data-mkedit]");if(m){mkEdit(m.dataset.mkedit);return}
  if(e.target.closest("[data-copy]")||e.target.closest("a.btn"))return;''')
s=s.replace('"Không ghi mật khẩu vào đây: trang được chia sẻ cho nhiều người. Lưu mật khẩu trong trình quản lý mật khẩu."','"Mật khẩu không ghi ở đây: dùng nút “Lưu mật khẩu” ở dòng liên kết, mật khẩu được lưu riêng cho bạn."')
open('links.js','w',encoding='utf-8').write(s)
print(s.count('mkCell'),s.count('mkInit'))
EOF
grep -n 'data-copy' app.js | grep -o 'toast("Đã chép[^)]*)' | head -2

