2	// Địa chỉ + tên tài khoản: dữ liệu chung. Mật khẩu: lưu riêng từng người ở data/users/<id>/matkhau (người khác, kể cả chủ trang, không đọc được).
3	S.mk={};S.mkReady=false;S.mkShow=new Set();
4	async function mkInit(){if(!S.db||!S.user||S.mkRef)return;let uid=null;try{uid=await S.user.id()}catch(e){}if(!uid)return;
5	  S.mkRef=S.db.collection("data/users/"+uid).doc("matkhau");S.mkRef.onSnapshot(d=>{S.mk=(d&&d.data())||{};S.mkReady=true;rLinks()},()=>{S.mkReady=false;rLinks()})}
6	function mkCell(l){if(!S.mkReady)return `<span class="d">—</span>`;const v=S.mk[l._id];
7	  return v?`<div class="tools" style="flex-wrap:nowrap"><code class="mk">${S.mkShow.has(l._id)?esc(v):"••••••"}</code><button type="button" class="btn sm" data-mkshow="${esc(l._id)}">${S.mkShow.has(l._id)?"Ẩn":"Hiện"}</button><button type="button" class="btn sm" data-copy="${esc(v)}" data-quiet="1">Chép</button><button type="button" class="btn sm" data-mkedit="${esc(l._id)}" title="Sửa mật khẩu">Sửa</button></div>`:`<button type="button" class="btn sm" data-mkedit="${esc(l._id)}">+ Lưu mật khẩu</button>`}
8	function mkEdit(id){const l=S.lienket.find(x=>x._id===id);if(!l||!S.mkRef)return;S.edit=null;
9	  S.form={fields:[],onSave:async()=>{const v=$("g_mk").value;const next=Object.assign({},S.mk);if(v)next[id]=v;else delete next[id];await S.mkRef.set(next)}};
10	  $("dTitle").textContent="Mật khẩu · "+l.ten;$("dSub").textContent="Chỉ mình bạn thấy: lưu trong vùng riêng của tài khoản bạn, người khác mở trang (kể cả chủ trang) không đọc được.";$("dFoot").hidden=false;
11	  $("dBody").innerHTML=`<div class="fld"><label for="g_tk">Tài khoản</label><input id="g_tk" value="${esc(l.tai_khoan||"")}" disabled></div><div class="fld"><label for="g_mk">Mật khẩu</label><input id="g_mk" type="password" autocomplete="off" value="${esc(S.mk[id]||"")}"><span class="d">Để trống rồi lưu để xoá mật khẩu.</span></div><label class="d" style="display:flex;gap:6px;align-items:center"><input type="checkbox" id="g_mkv"> Hiện mật khẩu khi nhập</label>`;
12	  $("g_mkv").onchange=e=>$("g_mk").type=e.target.checked?"text":"password";$("dSave").disabled=false;$("dPerm").textContent="";openD();setTimeout(()=>$("g_mk").focus(),50)}
13	const LKNHOM=["Hệ thống v1","Hệ thống v2 (dev/test)","Prototype BA","Khác"];
14	const isLocal=u=>/^[a-z]:\\|^\\\\/i.test(String(u||""));
15	function rLinks(){mkInit();
16	  $("nLink").textContent=S.lienket.length?`(${S.lienket.length})`:"";
17	  const q=norm($("qLk").value);
18	  const rows=S.lienket.filter(l=>!q||norm(Object.values(l).join(" ")).includes(q));
19	  const gs=[...new Set([...LKNHOM,...rows.map(l=>l.nhom||"Khác")])].map(g=>({g,ls:rows.filter(l=>(l.nhom||"Khác")===g).sort((a,b)=>(a.thu_tu||99)-(b.thu_tu||99)||String(a.ten).localeCompare(String(b.ten),"vi"))})).filter(x=>x.ls.length);
20	  $("lkGroups").innerHTML=gs.map(({g,ls})=>`<div class="card"><div class="grp"><h3>${esc(g)}</h3><span>${ls.length} liên kết</span></div><div class="tbl"><table><thead><tr><th style="width:26%">Hệ thống</th><th>Địa chỉ</th><th style="width:14%">Tài khoản</th><th style="width:240px">Mật khẩu <span class="d">(chỉ bạn thấy)</span></th><th style="width:130px"></th></tr></thead><tbody>${ls.map(l=>{const loc=isLocal(l.url),h=loc?null:l.url;return `<tr class="go" data-lk="${esc(l._id)}"><td><div class="t">${esc(l.ten)}</div>${l.ghi_chu?`<div class="d clamp">${esc(l.ghi_chu)}</div>`:""}</td><td><div class="c1 path" title="${esc(l.url)}">${esc(l.url)}</div>${loc?`<div class="d">File trong máy – trình duyệt không mở thẳng được, bấm Chép rồi dán vào thanh địa chỉ trình duyệt</div>`:/^https?:\/\/(192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)|\.ndop\//.test(l.url)?`<div class="d">Mạng nội bộ – cần kết nối mạng NADAT/VPN</div>`:""}</td><td>${l.tai_khoan?`<button type="button" class="btn sm" data-copy="${esc(l.tai_khoan)}" title="Chép tên tài khoản">${esc(l.tai_khoan)}</button>`:`<span class="d">—</span>`}</td><td>${mkCell(l)}</td><td><div class="tools" style="flex-wrap:nowrap">${h?`<a class="btn sm primary" href="${esc(h)}" target="_blank" rel="noopener">Mở</a>`:""}<button class="btn sm" type="button" data-copy="${esc(l.url)}">Chép</button></div></td></tr>`}).join("")}</tbody></table></div></div>`).join("")||`<div class="card empty">${S.loaded?"Chưa có liên kết nào. Bấm “Thêm liên kết”.":"Đang tải…"}</div>`;
21	}
22	function editLink(id){
23	  const l=S.lienket.find(x=>x._id===id)||{};
24	  showForm(l.ten||"Thêm liên kết","Mật khẩu không ghi ở đây: dùng nút “Lưu mật khẩu” ở dòng liên kết, mật khẩu được lưu riêng cho bạn.",[{k:"nhom",l:"Nhóm *",o:LKNHOM,v:l.nhom||LKNHOM[0]},{k:"ten",l:"Tên hệ thống *",v:l.ten},{k:"url",l:"Địa chỉ (URL hoặc đường dẫn file) *",v:l.url},{k:"tai_khoan",l:"Tên tài khoản đăng nhập (không ghi mật khẩu)",v:l.tai_khoan},{k:"ghi_chu",l:"Ghi chú",v:l.ghi_chu,t:"area"},{k:"thu_tu",l:"Thứ tự hiển thị",v:l.thu_tu||""}],
25	  async v=>{if(!v.ten||!v.url){toast("Cần nhập tên hệ thống và địa chỉ.");return false}
26	    if(/mật khẩu|password|pass\s*[:=]|\bpw\s*[:=]/i.test(v.tai_khoan+" "+v.ghi_chu)){toast("Có vẻ đang ghi mật khẩu. Hãy bỏ mật khẩu ra khỏi ô Tài khoản và Ghi chú.");return false}
27	    v.thu_tu=+v.thu_tu||99;const c=S.db.collection("lienket");if(l._id)await c.doc(l._id).set(v);else await c.add(v)},
28	  l._id?()=>S.db.collection("lienket").doc(l._id).delete():null);
29	}
30	$("qLk").addEventListener("input",rLinks);
31	document.addEventListener("click",e=>{if(e.target.closest("aside"))return;
32	  const t=e.target.closest("[data-tltab]");if(t){const k=t.dataset.tltab;document.querySelectorAll("[data-tltab]").forEach(b=>b.setAttribute("aria-selected",b===t));$("tlCay").hidden=k!=="cay";$("tlLink").hidden=k!=="link";return}
33	  let m=e.target.closest("[data-mkshow]");if(m){const k=m.dataset.mkshow;S.mkShow.has(k)?S.mkShow.delete(k):S.mkShow.add(k);rLinks();return}
34	  m=e.target.closest("[data-mkedit]");if(m){mkEdit(m.dataset.mkedit);return}
35	  if(e.target.closest("[data-copy]")||e.target.closest("a.btn"))return;
36	  const r=e.target.closest("[data-lk]");if(r)editLink(r.dataset.lk)});

