/* ---------- Liên kết hệ thống ---------- */
// Tài khoản dev/test: mật khẩu là dữ liệu chung của trang (người dùng yêu cầu), bấm là chép.
const LKNHOM=["Hệ thống v1","Hệ thống v2 (dev/test)","Prototype BA","Khác"];
const isLocal=u=>/^[a-z]:\\|^\\\\/i.test(String(u||""));
S.mkShow=new Set();
function mkCell(l){const v=l.mat_khau;if(!v)return `<button type="button" class="btn sm" data-lkedit="${esc(l._id)}">+ Thêm</button>`;
  return `<div class="tools" style="flex-wrap:nowrap"><button type="button" class="btn sm mkb" data-copy="${esc(v)}" data-quiet="1" title="Bấm để chép mật khẩu">${S.mkShow.has(l._id)?esc(v):"••••••"}</button><button type="button" class="btn sm" data-mkshow="${esc(l._id)}" title="${S.mkShow.has(l._id)?"Ẩn":"Hiện"} mật khẩu">${S.mkShow.has(l._id)?"Ẩn":"Hiện"}</button></div>`}
function rLinks(){
  $("nLink").textContent=S.lienket.length?`(${S.lienket.length})`:"";
  const q=norm($("qLk").value);
  const rows=S.lienket.filter(l=>!q||norm([l.nhom,l.ten,l.url,l.tai_khoan,l.ghi_chu].join(" ")).includes(q));
  const gs=[...new Set([...LKNHOM,...rows.map(l=>l.nhom||"Khác")])].map(g=>({g,ls:rows.filter(l=>(l.nhom||"Khác")===g).sort((a,b)=>(a.thu_tu||99)-(b.thu_tu||99)||String(a.ten).localeCompare(String(b.ten),"vi"))})).filter(x=>x.ls.length);
  $("lkGroups").innerHTML=gs.map(({g,ls})=>`<div class="card"><div class="grp"><h3>${esc(g)}</h3><span>${ls.length} liên kết · bấm tài khoản hoặc mật khẩu để chép</span></div><div class="tbl"><table><thead><tr><th style="width:24%">Hệ thống</th><th>Địa chỉ</th><th style="width:14%">Tài khoản</th><th style="width:190px">Mật khẩu</th><th style="width:130px"></th></tr></thead><tbody>${ls.map(l=>{const loc=isLocal(l.url),h=loc?null:l.url;return `<tr class="go" data-lk="${esc(l._id)}"><td><div class="t">${esc(l.ten)}</div>${l.ghi_chu?`<div class="d clamp">${esc(l.ghi_chu)}</div>`:""}</td><td><div class="c1 path" title="${esc(l.url)}">${esc(l.url)}</div>${loc?`<div class="d">File trong máy – bấm Chép rồi dán vào thanh địa chỉ trình duyệt</div>`:/^https?:\/\/(192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)|\.ndop\//.test(l.url)?`<div class="d">Mạng nội bộ – cần kết nối mạng NADAT/VPN</div>`:""}</td><td>${l.tai_khoan?`<button type="button" class="btn sm" data-copy="${esc(l.tai_khoan)}" data-quiet="1" title="Bấm để chép tài khoản">${esc(l.tai_khoan)}</button>`:`<span class="d">—</span>`}</td><td>${l.tai_khoan||l.mat_khau?mkCell(l):`<span class="d">—</span>`}</td><td><div class="tools" style="flex-wrap:nowrap">${h?`<a class="btn sm primary" href="${esc(h)}" target="_blank" rel="noopener">Mở</a>`:""}<button class="btn sm" type="button" data-copy="${esc(l.url)}">Chép</button></div></td></tr>`}).join("")}</tbody></table></div></div>`).join("")||`<div class="card empty">${S.loaded?"Chưa có liên kết nào. Bấm “Thêm liên kết”.":"Đang tải…"}</div>`;
}
function editLink(id){
  const l=S.lienket.find(x=>x._id===id)||{};
  showForm(l.ten||"Thêm liên kết","Tài khoản dev/test: mật khẩu hiển thị cho mọi người mở trang.",[{k:"nhom",l:"Nhóm *",o:LKNHOM,v:l.nhom||LKNHOM[0]},{k:"ten",l:"Tên hệ thống *",v:l.ten},{k:"url",l:"Địa chỉ (URL hoặc đường dẫn file) *",v:l.url},{k:"tai_khoan",l:"Tài khoản",v:l.tai_khoan},{k:"mat_khau",l:"Mật khẩu",v:l.mat_khau},{k:"ghi_chu",l:"Ghi chú",v:l.ghi_chu,t:"area"},{k:"thu_tu",l:"Thứ tự hiển thị",v:l.thu_tu||""}],
  async v=>{if(!v.ten||!v.url){toast("Cần nhập tên hệ thống và địa chỉ.");return false}
    v.thu_tu=+v.thu_tu||99;const c=S.db.collection("lienket");if(l._id)await c.doc(l._id).set(v);else await c.add(v)},
