  const rows=S.lienket.filter(l=>!q||norm(Object.values(l).join(" ")).includes(q));
  const gs=[...new Set([...LKNHOM,...rows.map(l=>l.nhom||"Khác")])].map(g=>({g,ls:rows.filter(l=>(l.nhom||"Khác")===g).sort((a,b)=>(a.thu_tu||99)-(b.thu_tu||99)||String(a.ten).localeCompare(String(b.ten),"vi"))})).filter(x=>x.ls.length);
  $("lkGroups").innerHTML=gs.map(({g,ls})=>`<div class="card"><div class="grp"><h3>${esc(g)}</h3><span>${ls.length} liên kết</span></div><div class="tbl"><table><thead><tr><th style="width:26%">Hệ thống</th><th>Địa chỉ</th><th style="width:14%">Tài khoản</th><th style="width:240px">Mật khẩu <span class="d">(chỉ bạn thấy)</span></th><th style="width:130px"></th></tr></thead><tbody>${ls.map(l=>{const loc=isLocal(l.url),h=loc?null:l.url;return `<tr class="go" data-lk="${esc(l._id)}"><td><div class="t">${esc(l.ten)}</div>${l.ghi_chu?`<div class="d clamp">${esc(l.ghi_chu)}</div>`:""}</td><td><div class="c1 path" title="${esc(l.url)}">${esc(l.url)}</div>${loc?`<div class="d">File trong máy – trình duyệt không mở thẳng được, bấm Chép rồi dán vào thanh địa chỉ trình duyệt</div>`:/^https?:\/\/(192\.168\.|10\.|172\.(1[6-9]|2\d|3[01])\.)|\.ndop\//.test(l.url)?`<div class="d">Mạng nội bộ – cần kết nối mạng NADAT/VPN</div>`:""}</td><td>${l.tai_khoan?`<button type="button" class="btn sm" data-copy="${esc(l.tai_khoan)}" title="Chép tên tài khoản">${esc(l.tai_khoan)}</button>`:`<span class="d">—</span>`}</td><td>${mkCell(l)}</td><td><div class="tools" style="flex-wrap:nowrap">${h?`<a class="btn sm primary" href="${esc(h)}" target="_blank" rel="noopener">Mở</a>`:""}<button class="btn sm" type="button" data-copy="${esc(l.url)}">Chép</button></div></td></tr>`}).join("")}</tbody></table></div></div>`).join("")||`<div class="card empty">${S.loaded?"Chưa có liên kết nào. Bấm “Thêm liên kết”.":"Đang tải…"}</div>`;
}
function editLink(id){
  const l=S.lienket.find(x=>x._id===id)||{};
  showForm(l.ten||"Thêm liên kết","Mật khẩu không ghi ở đây: dùng nút “Lưu mật khẩu” ở dòng liên kết, mật khẩu được lưu riêng cho bạn.",[{k:"nhom",l:"Nhóm *",o:LKNHOM,v:l.nhom||LKNHOM[0]},{k:"ten",l:"Tên hệ thống *",v:l.ten},{k:"url",l:"Địa chỉ (URL hoặc đường dẫn file) *",v:l.url},{k:"tai_khoan",l:"Tên tài khoản đăng nhập (không ghi mật khẩu)",v:l.tai_khoan},{k:"ghi_chu",l:"Ghi chú",v:l.ghi_chu,t:"area"},{k:"thu_tu",l:"Thứ tự hiển thị",v:l.thu_tu||""}],
  async v=>{if(!v.ten||!v.url){toast("Cần nhập tên hệ thống và địa chỉ.");return false}
    if(/mật khẩu|password|pass\s*[:=]|\bpw\s*[:=]/i.test(v.tai_khoan+" "+v.ghi_chu)){toast("Có vẻ đang ghi mật khẩu. Hãy bỏ mật khẩu ra khỏi ô Tài khoản và Ghi chú.");return false}
    v.thu_tu=+v.thu_tu||99;const c=S.db.collection("lienket");if(l._id)await c.doc(l._id).set(v);else await c.add(v)},
  l._id?()=>S.db.collection("lienket").doc(l._id).delete():null);
}
$("qLk").addEventListener("input",rLinks);
document.addEventListener("click",e=>{if(e.target.closest("aside"))return;
  const t=e.target.closest("[data-tltab]");if(t){const k=t.dataset.tltab;document.querySelectorAll("[data-tltab]").forEach(b=>b.setAttribute("aria-selected",b===t));$("tlCay").hidden=k!=="cay";$("tlLink").hidden=k!=="link";return}
  let m=e.target.closest("[data-mkshow]");if(m){const k=m.dataset.mkshow;S.mkShow.has(k)?S.mkShow.delete(k):S.mkShow.add(k);rLinks();return}
  m=e.target.closest("[data-mkedit]");if(m){mkEdit(m.dataset.mkedit);return}
  if(e.target.closest("[data-copy]")||e.target.closest("a.btn"))return;
  const r=e.target.closest("[data-lk]");if(r)editLink(r.dataset.lk)});

